-- Derek's week 2 (hero derek, days 8-14): episodes, turns, phrases and his calendar.
-- The same week as db/seed/20-week2.sql and 21-trip.sql, seen from his side: the postmortem, the Summit Retail kickoff,
-- delegating to Jun, the code review swap, the handoff, covering while Jun is in Ridgeport (days 11-12), and the weekend.
-- Push: node tools/dolt.mjs push db/seed/54-derek-week2.sql

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_d8_coffee', 'Fog on Lake Avenue', '레이크 애비뉴의 안개', 'coffee_cart', 'nina', 8, 8, '07:00', '10:30', NULL,
   'A foggy Monday morning. Your punch card was full last week, so today''s drink is free. Talk about the slow drive in, treat yourself, and tell Nina about the barbecue.', '안개 낀 월요일 아침입니다. 지난주에 쿠폰 카드가 다 차서 오늘 음료는 공짜입니다. 느릿느릿했던 출근길 이야기를 하고, 자신에게 작은 사치를 부리고, 니나에게 바비큐 이야기를 들려주세요.',
   0, 9, 10, 'food,coffee,small-talk,weather', 'derek'),
  ('dk_d8_risk', 'How risky is it?', '얼마나 위험한가요?', 'office_meeting', 'priya', 8, 8, '11:30', '16:30', NULL,
   'The kickoff call with Summit Retail is over, and Priya wants the technical risk in words she can use. Say "it depends" well, give a range, and propose a phased rollout.', '서밋 리테일 킥오프 콜이 끝났고, 프리야는 기술적 위험을 자신이 쓸 수 있는 말로 듣고 싶어 합니다. "상황에 따라 다르다"를 제대로 말하고, 범위로 추정하고, 단계별 적용을 제안하세요.',
   0, 0, 20, 'meeting,client,risk,estimate', 'derek'),
  ('dk_d8_postmortem', 'No blame, just causes', '탓하지 않고 원인만', 'office_it', 'sam', 8, 8, '13:00', '18:00', NULL,
   'You go through your postmortem of last Thursday''s outage with Sam and Maya. Keep it blameless, tell the trigger from the root cause, and give every action item an owner and a date.', '지난 목요일 장애의 사후 분석 보고서를 샘, 마야와 함께 검토합니다. 누구도 탓하지 말고, 계기와 근본 원인을 구분하고, 후속 조치마다 담당자와 날짜를 정하세요.',
   0, 0, 30, 'meeting,incident,postmortem,it', 'derek'),
  ('dk_d9_delegate', 'Letting go of a task', '일을 맡기기', 'office_desk', 'jun', 9, 9, '09:00', '12:30', NULL,
   'You were about to build the certificate alert yourself. Hand it to Jun instead: say what done looks like, when it is due, and how much freedom he has.', '인증서 경보를 직접 만들려던 참이었습니다. 대신 준에게 맡기세요. 완료의 기준이 무엇인지, 언제까지인지, 얼마나 자유롭게 해도 되는지 말해 주세요.',
   0, 0, 10, 'coworker,delegating,mentoring,leadership', 'derek');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_d9_lunch', 'Ordering in on a rainy day', '비 오는 날 배달 시켜 먹기', 'office_kitchen', 'sam', 9, 9, '11:30', '14:30', NULL,
   'Nobody wants to go out in this rain. Go in on a pizza with Sam: agree on the toppings, split the bill, and get change for a twenty.', '이런 비에 나가고 싶은 사람은 없습니다. 샘과 돈을 모아 피자를 시키세요. 토핑을 정하고, 값을 나누고, 20달러짜리를 거슬러 받으세요.',
   -13, 40, 20, 'food,lunch,small-talk,money', 'derek'),
  ('dk_d9_review', 'The reviewer gets reviewed', '리뷰어가 리뷰를 받다', 'office_desk_team', 'jun', 9, 10, '13:00', '18:30', NULL,
   'You and Jun trade code reviews. This time he has comments on your pull request. Invite honest feedback, take it graciously, and disagree on one point without getting defensive.', '준과 코드 리뷰를 주고받습니다. 이번에는 그가 당신의 풀 리퀘스트에 의견을 냅니다. 솔직한 피드백을 청하고, 기분 좋게 받아들이고, 한 가지는 방어적이지 않게 반대하세요.',
   0, 0, 30, 'dev,code-review,feedback,disagreeing', 'derek'),
  ('dk_d10_stretch', 'The one-page plan', '한 장짜리 계획', 'office_manager', 'maya', 10, 10, '08:30', '13:00', NULL,
   'You follow up on last week''s 1:1. Show Maya the plan, tell her honestly how delegating went, ask for a bigger role on the Summit Retail project, and agree on a timeline.', '지난주 1:1의 후속 면담입니다. 마야에게 계획을 보여 주고, 일을 맡겨 보니 어땠는지 솔직히 말하고, 서밋 리테일 프로젝트에서 더 큰 역할을 요청하고, 일정에 합의하세요.',
   0, 0, 10, 'manager,career,1:1,follow-up', 'derek'),
  ('dk_d10_handoff', 'Before you fly', '비행기 타기 전에', 'office_desk_team', 'jun', 10, 10, '14:00', '18:30', NULL,
   'Jun flies to Ridgeport tomorrow and hands his work over to you. Ask the right questions: what is done, what is left, where the docs are, and who to contact.', '준이 내일 리지포트로 떠나며 당신에게 일을 넘깁니다. 필요한 질문을 하세요. 무엇이 끝났고, 무엇이 남았고, 문서는 어디 있고, 누구에게 연락하면 되는지요.',
   0, 0, 20, 'coworker,handoff,covering,questions', 'derek');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_d11_call', 'A quick call to Ridgeport', '리지포트로 짧은 전화', 'office_desk_team', 'jun', 11, 11, '12:00', '16:00', NULL,
   'Jun is in Ridgeport, and a list you need is missing from his ticket. Call his cell: ask if it is a good time, keep it short, and let him get back to the client.', '준은 리지포트에 있고, 당신에게 필요한 목록이 그의 티켓에 빠져 있습니다. 휴대전화로 전화하세요. 통화 괜찮은지 묻고, 짧게 끝내고, 그가 고객에게 돌아갈 수 있게 해 주세요.',
   0, 0, 10, 'phone,coworker,covering', 'derek'),
  ('dk_d11_unblock', 'An answer Priya can forward', '프리야가 그대로 전달할 수 있는 답', 'office_meeting', 'priya', 11, 11, '13:00', '18:00', 'dk_d11_call',
   'Summit Retail''s IT lead has questions about the bug, and Priya is stuck. Give her the facts in plain English, add a caveat instead of overpromising, and offer to join a call.', '서밋 리테일의 IT 책임자가 버그에 대해 물어 왔는데 프리야가 답을 못 하고 있습니다. 쉬운 말로 사실을 알려 주고, 무리한 약속 대신 단서를 달고, 통화에 함께 들어가겠다고 제안하세요.',
   0, 0, 20, 'meeting,client,covering,explaining', 'derek'),
  ('dk_d12_panel', 'On the interview panel', '면접관이 되다', 'office_hr', 'linda', 12, 12, '09:00', '15:00', NULL,
   'Linda wants you on the interview panel for a backend developer. Talk about what you look for, what a red flag is, which questions are off-limits, and ask about comp time for your on-call week.', '린다가 백엔드 개발자 면접에 당신이 면접관으로 들어와 주길 바랍니다. 무엇을 볼지, 무엇이 위험 신호인지, 어떤 질문이 금지인지 이야기하고, 온콜 주간에 대한 보상 휴가도 물어보세요.',
   0, 0, 10, 'hr,interview,hiring,benefits', 'derek'),
  ('dk_d12_signed', 'Good news from Ridgeport', '리지포트에서 온 좋은 소식', 'office_desk_team', 'jun', 12, 12, '13:00', '18:00', NULL,
   'Jun calls from the airport in Ridgeport: the contract is signed. Congratulate him, tell him how things went while he was away, and make him rest this weekend.', '준이 리지포트 공항에서 전화합니다. 계약이 체결됐습니다. 축하해 주고, 그가 없는 동안 일이 어떻게 됐는지 알려 주고, 이번 주말에는 쉬게 하세요.',
   0, 0, 20, 'phone,coworker,covering,congratulations', 'derek');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_w2_mower', 'The mower comes home', '돌아온 잔디 깎는 기계', 'derek_door', 'carl', 13, 13, '09:00', '15:00', NULL,
   'Carl brings back your lawn mower, fixed. Thank him properly, offer to pay for the parts, ask about your leaking gutter, and say yes to his barbecue.', '칼이 고친 잔디 깎는 기계를 가져왔습니다. 제대로 고마움을 전하고, 부품값을 내겠다고 하고, 새는 빗물받이에 대해 묻고, 그의 바비큐 초대를 받아들이세요.',
   0, 0, 10, 'neighbor,homeowner,weekend,favor', 'derek'),
  ('dk_w2_market', 'A rain check on the ice cream', '아이스크림 레인 체크', 'market_checkout', 'mike', 13, 13, '09:00', '16:00', NULL,
   'You promised to bring dessert to Carl''s barbecue, but the ice cream on sale is sold out. Ask Mike for a rain check, and take the store brand for today.', '칼의 바비큐에 디저트를 가져가기로 했는데, 할인하는 아이스크림이 다 팔렸습니다. 마이크에게 레인 체크를 부탁하고, 오늘은 매장 자체 브랜드 제품을 사세요.',
   -4, 0, 20, 'shopping,market,weekend,sale', 'derek'),
  ('dk_w2_brunch', 'A rainy Sunday at the Sunny Side', '비 오는 일요일, 서니 사이드에서', 'diner_counter', 'rosa', 14, 14, '08:00', '14:00', NULL,
   'Showers all day, and the diner is packed. Take a seat at the counter, order brunch just the way you like it, tell Rosa the news about Jun, and ask for a box and the check.', '종일 소나기가 오고 다이너는 만석입니다. 카운터에 앉아 브런치를 입맛대로 주문하고, 로사에게 준의 소식을 전하고, 포장 상자와 계산서를 부탁하세요.',
   -19, 40, 10, 'food,diner,weekend,brunch,tipping', 'derek');

-- dk_d8_coffee: Fog on Lake Avenue

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_coffee', 1, 'nina',
   'Monday morning. Fog hangs over Lake Avenue, and you can barely see the coffee cart until you are standing in front of it.', '월요일 아침입니다. 레이크 애비뉴에 안개가 자욱해서 바로 앞에 설 때까지 커피 카트가 잘 보이지 않습니다.',
   'Morning, Derek! I can barely see across the street. How was the drive in?', 'Say traffic was crawling the whole way, and it took you twice as long as usual.', '오는 내내 차들이 기어가다시피 했고, 평소보다 두 배나 걸렸다고 하세요.',
   '[{"any":["crawling","crawl","crawled"]},{"all":["twice as long"]},{"all":["bumper to bumper"]}]',
   'Traffic was crawling the whole way. It took me twice as long as usual.',
   '["The flight was smooth. We landed twenty minutes early.","It was great. I walked along the beach at sunset.","The elevator was out of order, so I took the stairs."]',
   '["Describe slow traffic and compare it with a normal day.","Key words: crawling, twice as long"]', '["느린 교통 상황을 묘사하고 평소와 비교하세요.","핵심 단어: crawling, twice as long"]',
   'nina', 'I believe it. Half my regulars are running late. It''s supposed to burn off by noon, though.', '그럴 만해요. 단골 절반이 늦고 있어요. 그래도 정오쯤엔 걷힌대요.'),
  ('dk_d8_coffee', 2, 'nina',
   'She reaches for a large cup, then stops.', '그녀가 큰 컵을 집으려다 멈춥니다.',
   'The usual? Oh, wait. Your card was full last week. This one''s on the house, so get whatever you want.', 'Say that in that case you will treat yourself, and ask her to make it a large latte with an extra shot.', '그렇다면 오늘은 좀 누려 보겠다고 하고, 샷을 추가한 라테 라지로 해 달라고 하세요.',
   '[{"all":["treat myself"]},{"all":["extra shot"]},{"any":["latte"]}]',
   'In that case, I''ll treat myself. Make it a large latte with an extra shot.',
   '["In that case, I''ll take the stairs.","In that case, I''d like an aisle seat.","In that case, please send it to my manager."]',
   '["A free drink is a chance for something nicer than usual.","Key words: treat myself, make it a, extra shot"]', '["공짜 음료는 평소보다 좋은 것을 고를 기회입니다.","핵심 단어: treat myself, make it a, extra shot"]',
   'nina', 'A latte! Look at you, living on the edge.', '라테라니! 오늘 아주 과감하시네요.'),
  ('dk_d8_coffee', 3, 'nina',
   'The milk steamer hisses. Nina talks over it.', '우유 스티머가 쉭쉭 소리를 냅니다. 니나가 그 소리 너머로 말합니다.',
   'So how was the barbecue? Mike told me you nearly bought out the market.', 'Say it was a blast, the weather could not have been better, and your neighbor''s potato salad stole the show.', '정말 즐거웠고, 날씨는 더할 나위 없이 좋았고, 이웃의 감자 샐러드가 가장 인기였다고 하세요.',
   '[{"all":["a blast"]},{"all":["stole the show"]},{"all":["could not have been better"]},{"all":["potato salad"]}]',
   'It was a blast. The weather couldn''t have been better, and my neighbor''s potato salad stole the show.',
   '["It was canceled. The flight was overbooked.","It was delayed, so I took a later bus.","It was too spicy, so I sent it back."]',
   '["Say how much fun it was, and what everybody liked best.","Key words: a blast, couldn''t have been better, stole the show"]', '["얼마나 즐거웠는지, 모두가 무엇을 가장 좋아했는지 말하세요.","핵심 단어: a blast, couldn''t have been better, stole the show"]',
   'nina', 'A potato salad beat your burgers? Ouch.', '감자 샐러드가 데릭의 버거를 이겼어요? 저런.'),
  ('dk_d8_coffee', 4, 'nina',
   'She snaps a lid on the cup and slides it across the counter.', '그녀가 컵에 뚜껑을 딱 닫아 카운터 너머로 밀어 줍니다.',
   'Here you go. Big week ahead?', 'Say you have a new project kicking off today, so you will need all the caffeine you can get.', '오늘 새 프로젝트가 시작돼서 카페인이 있는 대로 다 필요하다고 하세요.',
   '[{"any":["kicking off","kicks off","kickoff","caffeine"]},{"all":["kick off"]}]',
   'We''ve got a new project kicking off today, so I''ll need all the caffeine I can get.',
   '["I''ve got a dentist appointment, so I can''t stay long.","My week was fine. I mostly stayed home.","I''m getting off at the next stop."]',
   '["\\"Kick off\\" = start (a project, a meeting, a game).","Key words: kicking off, caffeine"]', '["kick off는 프로젝트나 회의, 경기를 시작한다는 뜻입니다.","핵심 단어: kicking off, caffeine"]',
   'nina', 'Then go get ''em. And drive safe tonight!', '그럼 가서 멋지게 해내요. 저녁에 운전 조심하고요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d8_coffee.crawling', 'dk_d8_coffee', 'Traffic was crawling.', '차들이 기어가다시피 했어요.', '"Crawl" = move very slowly. Also: "bumper to bumper".', 'crawl은 아주 느리게 움직인다는 뜻입니다. bumper to bumper라고도 합니다.', 'small-talk'),
  ('dk_d8_coffee.twice_as_long', 'dk_d8_coffee', 'It took me twice as long as usual.', '평소보다 두 배나 걸렸어요.', '"Twice as … as" compares: two times the normal amount.', '"twice as … as"는 평소의 두 배라고 비교하는 표현입니다.', 'small-talk'),
  ('dk_d8_coffee.burn_off', 'dk_d8_coffee', 'It''s supposed to burn off by noon.', '정오쯤엔 걷힌대요.', 'Fog "burns off" when the sun warms it away. "Supposed to" = that is the forecast.', '안개가 햇볕에 걷히는 것을 burn off라고 합니다. supposed to는 예보가 그렇다는 뜻입니다.', 'small-talk'),
  ('dk_d8_coffee.treat_myself', 'dk_d8_coffee', 'I''ll treat myself.', '오늘은 저한테 선물 좀 할게요.', 'Allow yourself something nice that you do not usually have.', '평소에는 잘 하지 않는 좋은 것을 자신에게 허락한다는 뜻입니다.', 'food'),
  ('dk_d8_coffee.make_it_a', 'dk_d8_coffee', 'Make it a large latte with an extra shot.', '샷 추가한 라테 라지로 해 주세요.', '"Make it a …" changes or decides an order. An extra shot is one more shot of espresso.', '"Make it a …"는 주문을 바꾸거나 정할 때 씁니다. extra shot은 에스프레소 샷 추가입니다.', 'food'),
  ('dk_d8_coffee.a_blast', 'dk_d8_coffee', 'It was a blast.', '정말 즐거웠어요.', '"A blast" = a lot of fun. Casual.', 'a blast는 아주 재미있었다는 편한 표현입니다.', 'small-talk'),
  ('dk_d8_coffee.stole_the_show', 'dk_d8_coffee', 'The potato salad stole the show.', '감자 샐러드가 주인공이었어요.', '"Steal the show" = get more attention and praise than anything else.', 'steal the show는 다른 무엇보다 관심과 칭찬을 많이 받는다는 뜻입니다.', 'small-talk'),
  ('dk_d8_coffee.kicking_off', 'dk_d8_coffee', 'We''ve got a new project kicking off today.', '오늘 새 프로젝트가 시작돼요.', '"Kick off" = start. The first meeting of a project is "the kickoff".', 'kick off는 시작한다는 뜻입니다. 프로젝트의 첫 회의를 the kickoff라고 합니다.', 'office');

-- dk_d8_risk: How risky is it?

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_risk', 1, 'priya',
   'The kickoff call with Summit Retail has just ended. Jun has gone back to his desk. Priya closes the door of the meeting room.', '서밋 리테일 킥오프 콜이 방금 끝났습니다. 준은 자리로 돌아갔습니다. 프리야가 회의실 문을 닫습니다.',
   'Okay, you heard Greg. Live inventory for forty stores. Give it to me straight: how risky is this?', 'Say the dashboard itself is straightforward, and the big unknown is their point-of-sale system.', '대시보드 자체는 어렵지 않고, 가장 불확실한 것은 그쪽의 POS 시스템이라고 하세요.',
   '[{"any":["unknown","unknowns","straightforward"]},{"all":["point of sale"]}]',
   'The dashboard itself is straightforward. The big unknown is their point-of-sale system.',
   '["The diner itself is fine. The big problem is parking.","The risk is low. It only rains on Tuesdays.","Give me a large one, with room for cream."]',
   '["Separate the easy part from the part nobody knows yet.","Key words: straightforward, the big unknown"]', '["쉬운 부분과 아직 아무도 모르는 부분을 나누어 말하세요.","핵심 단어: straightforward, the big unknown"]',
   'priya', 'The old one that spits out a file every night. Right.', '매일 밤 파일을 하나씩 뱉어 내는 그 오래된 시스템 말이죠. 그렇군요.'),
  ('dk_d8_risk', 2, 'priya',
   'Priya opens the timeline on her laptop.', '프리야가 노트북에서 일정표를 엽니다.',
   'So can we hit November first or not? I need a yes or a no.', 'Say it depends on how soon you get API access: if you get it this week, you are in good shape; if not, the date is at risk.', 'API 접근 권한을 얼마나 빨리 받느냐에 달렸다고 하세요. 이번 주에 받으면 문제없고, 아니면 그 날짜가 위험하다고요.',
   '[{"all":["depends on"]},{"all":["at risk"]},{"all":["good shape"]}]',
   'It depends on how soon we get API access. If we get it this week, we''re in good shape. If not, the date is at risk.',
   '["No. I''d rather sit by the window.","Yes, I''d like it well done.","It''s at gate twelve, on the left."]',
   '["Do not stop at \\"it depends\\". Say what it depends on, and what happens either way.","Key words: it depends on, in good shape, at risk"]', '["\\"it depends\\"에서 멈추지 마세요. 무엇에 달렸는지, 경우마다 어떻게 되는지 말하세요.","핵심 단어: it depends on, in good shape, at risk"]',
   'priya', 'Okay. That''s an "it depends" I can actually use.', '좋아요. 그건 제가 실제로 써먹을 수 있는 "상황에 따라"네요.'),
  ('dk_d8_risk', 3, 'priya',
   'She types a note: "API access this week."', '그녀가 "이번 주 안에 API 접근 권한"이라고 메모합니다.',
   'Ballpark, how long is phase one? I won''t hold you to it.', 'Give a range, not a single number: six to eight weeks, assuming their API does what they say it does.', '숫자 하나가 아니라 범위로 말하세요. 그쪽 API가 말한 대로 동작한다는 전제로 6주에서 8주라고요.',
   '[{"any":["assuming","range"]},{"all":["six to eight"]},{"all":["6 to 8"]}]',
   'Ballpark, six to eight weeks, assuming their API does what they say it does.',
   '["About six dollars, with tax.","Two blocks north, across from the bank.","Every fifteen minutes, until midnight."]',
   '["Give a range and name the assumption behind it.","Key words: six to eight weeks, assuming"]', '["범위로 말하고 그 뒤에 깔린 전제를 밝히세요.","핵심 단어: six to eight weeks, assuming"]',
   'priya', 'Six to eight, with an assumption attached. Got it.', '6주에서 8주, 전제 하나 붙여서. 알겠어요.'),
  ('dk_d8_risk', 4, 'priya',
   'Priya puts down her pen.', '프리야가 펜을 내려놓습니다.',
   'And what keeps you up at night?', 'Say the worst case is that the data from the stores is messy, and you would rather find that out early than in October.', '최악의 경우는 매장 데이터가 엉망인 것이고, 그걸 10월이 아니라 일찍 알아내고 싶다고 하세요.',
   '[{"all":["worst case"]},{"any":["messy","dirty"]},{"all":["find that out early"]},{"all":["find out early"]}]',
   'Worst case, the data from the stores is messy. I''d rather find that out early than in October.',
   '["My neighbor''s dog. It barks all night.","Too much coffee after dinner.","The people upstairs are moving furniture."]',
   '["Name the worst thing that could happen, and when you want to know.","Key words: worst case, messy, find that out early"]', '["일어날 수 있는 가장 나쁜 일과, 그것을 언제 알고 싶은지 말하세요.","핵심 단어: worst case, messy, find that out early"]',
   'priya', 'Agreed. Bad news doesn''t get better with age.', '동의해요. 나쁜 소식은 묵힌다고 좋아지지 않죠.'),
  ('dk_d8_risk', 5, 'priya',
   'She stands at the whiteboard with a marker.', '그녀가 마커를 들고 화이트보드 앞에 섭니다.',
   'So how do we take some of that risk off the table?', 'Propose a phased rollout: pilot with five stores first, then roll it out to the rest.', '단계별 적용을 제안하세요. 먼저 매장 다섯 곳에서 시범 운영하고, 그다음 나머지로 넓히자고요.',
   '[{"any":["pilot","phased"]},{"all":["roll it out"]},{"all":["five stores"]}]',
   'I''d propose a phased rollout. We pilot with five stores first, then roll it out to the rest.',
   '["I''d propose a toast. To the happy couple!","I''d take the first exit and turn left.","We could split the check five ways."]',
   '["Start small, learn, then expand.","Key words: phased rollout, pilot, roll it out"]', '["작게 시작해서 배우고, 그다음 넓히세요.","핵심 단어: phased rollout, pilot, roll it out"]',
   'priya', 'A five-store pilot. I love it. I''ll float it with Greg on tomorrow''s call.', '매장 다섯 곳 시범 운영. 아주 좋아요. 내일 통화에서 그렉에게 슬쩍 제안해 볼게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d8_risk.give_it_straight', 'dk_d8_risk', 'Give it to me straight.', '돌려 말하지 말고 솔직하게 말해 줘요.', 'Asks for the honest truth, even if it is bad news.', '나쁜 소식이라도 있는 그대로 말해 달라는 뜻입니다.', 'meeting'),
  ('dk_d8_risk.big_unknown', 'dk_d8_risk', 'The big unknown is their point-of-sale system.', '가장 불확실한 건 그쪽 POS 시스템이에요.', 'An "unknown" is something you cannot estimate yet because you have no information.', 'unknown은 정보가 없어 아직 추정할 수 없는 것을 말합니다.', 'meeting'),
  ('dk_d8_risk.it_depends_on', 'dk_d8_risk', 'It depends on how soon we get API access.', 'API 접근 권한을 얼마나 빨리 받느냐에 달렸어요.', 'A good "it depends" always says what it depends on.', '좋은 "it depends"는 무엇에 달렸는지를 꼭 말합니다.', 'meeting'),
  ('dk_d8_risk.at_risk', 'dk_d8_risk', 'The date is at risk.', '그 날짜는 위험해요.', 'A calm way to warn that a deadline may be missed. The opposite: "We''re in good shape."', '마감을 못 지킬 수 있다고 차분하게 경고하는 표현입니다. 반대는 "We''re in good shape."입니다.', 'meeting'),
  ('dk_d8_risk.ballpark', 'dk_d8_risk', 'Ballpark, six to eight weeks.', '대략 6주에서 8주요.', 'A "ballpark (figure)" is a rough estimate. From baseball.', 'ballpark (figure)는 대략적인 추정치입니다. 야구에서 온 말입니다.', 'meeting'),
  ('dk_d8_risk.hold_you_to_it', 'dk_d8_risk', 'I won''t hold you to it.', '꼭 지키라고 하지는 않을게요.', '"Hold someone to" a number = make them keep it as a promise.', 'hold someone to는 그 숫자를 약속으로 지키게 한다는 뜻입니다.', 'meeting'),
  ('dk_d8_risk.worst_case', 'dk_d8_risk', 'Worst case, the data is messy.', '최악의 경우, 데이터가 엉망일 거예요.', 'Short for "in the worst case". The opposite is "best case".', '"in the worst case"를 줄인 말입니다. 반대는 best case입니다.', 'meeting'),
  ('dk_d8_risk.phased_rollout', 'dk_d8_risk', 'I''d propose a phased rollout.', '단계별 적용을 제안합니다.', 'Releasing in steps. A "pilot" is a small first test with real users.', '여러 단계로 나누어 내놓는 것입니다. pilot은 실제 사용자와 하는 작은 첫 시험입니다.', 'meeting');

-- dk_d8_postmortem: No blame, just causes

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_postmortem', 1, 'maya',
   'Monday afternoon in Sam''s room. Your postmortem of last Thursday''s outage is on the big monitor. Maya has pulled up a chair.', '월요일 오후, 샘의 방입니다. 지난 목요일 장애에 대해 당신이 쓴 사후 분석 보고서가 큰 모니터에 떠 있습니다. 마야가 의자를 끌어다 앉았습니다.',
   'Thanks for writing this up, Derek. Before we start: how do you want to run this?', 'Say you want to keep it blameless: you are here to fix the process, not to point fingers.', '누구도 탓하지 않는 방식으로 하자고 하세요. 손가락질하려는 게 아니라 절차를 고치려고 모였다고요.',
   '[{"any":["blameless"]},{"all":["point fingers"]},{"all":["pointing fingers"]},{"all":["fix the process"]}]',
   'Let''s keep it blameless. We''re here to fix the process, not to point fingers.',
   '["Let''s keep it short. The game starts at seven.","Let''s take the scenic route along the beach.","Let''s split a pizza. I''m starving."]',
   '["Set the rule first: look for causes, not for someone to blame.","Key words: blameless, point fingers"]', '["규칙부터 정하세요. 탓할 사람이 아니라 원인을 찾는다고요.","핵심 단어: blameless, point fingers"]',
   'sam', 'Good, because I''ve been losing sleep over that certificate.', '다행이네요. 그 인증서 때문에 잠을 설쳤거든요.'),
  ('dk_d8_postmortem', 2, 'sam',
   'Sam stares at the timeline on the screen: "8:57, certificate expires."', '샘이 화면의 타임라인을 물끄러미 봅니다. "8:57, 인증서 만료."',
   'Be honest, though. It was my certificate. I should have caught it.', 'Reassure him that it could have happened to anyone: the renewal reminder went to someone who left the company two years ago.', '누구에게나 일어날 수 있는 일이었다고 안심시키세요. 갱신 알림이 2년 전에 퇴사한 사람에게 갔다고요.',
   '[{"all":["happened to anyone"]},{"all":["happen to anyone"]},{"any":["reminder","reminders"]},{"all":["not on you"]}]',
   'It could have happened to anyone. The renewal reminder went to someone who left two years ago.',
   '["It could be worse. At least the pie was good.","It was my umbrella. I left it in the lobby.","Someone parked in my spot two days ago."]',
   '["Move the talk from the person to the system.","Key words: could have happened to anyone, reminder"]', '["이야기를 사람에서 시스템으로 옮기세요.","핵심 단어: could have happened to anyone, reminder"]',
   'sam', 'Yeah. An inbox nobody reads. That''s the real bug.', '그러게요. 아무도 안 읽는 메일함. 그게 진짜 버그네요.'),
  ('dk_d8_postmortem', 3, 'maya',
   'Maya scrolls to the section called "Causes".', '마야가 "원인" 항목으로 화면을 내립니다.',
   'So what''s the root cause, as opposed to the trigger?', 'Say the expired certificate was just the trigger; the root cause is that nobody owned the renewal, so it fell through the cracks.', '만료된 인증서는 계기일 뿐이고, 근본 원인은 갱신을 맡은 사람이 없어서 빠뜨리게 된 것이라고 하세요.',
   '[{"all":["fell through the cracks"]},{"all":["root cause"]},{"all":["nobody owned"]},{"all":["no owner"]}]',
   'The expired certificate was just the trigger. The root cause is that nobody owned the renewal, so it fell through the cracks.',
   '["The trigger was a flat tire on the highway.","The cause is simple: I skipped breakfast.","The roots of that old tree are lifting the sidewalk."]',
   '["The trigger is what set it off; the root cause is why it was possible at all.","Key words: trigger, root cause, fell through the cracks"]', '["trigger는 일을 터뜨린 계기이고, root cause는 그 일이 가능했던 이유입니다.","핵심 단어: trigger, root cause, fell through the cracks"]',
   'maya', 'No owner. That''s the line I want at the top of the page.', '담당자 없음. 그 문장을 보고서 맨 위에 두고 싶네요.'),
  ('dk_d8_postmortem', 4, 'maya',
   'She opens an empty table with three columns: what, who, when.', '그녀가 무엇, 누가, 언제의 세 칸짜리 빈 표를 엽니다.',
   'Okay, action items. What do we do, who owns it, and by when?', 'Say Sam moves the renewals to a shared calendar by Friday, and you will own the expiry alert.', '샘이 금요일까지 갱신 일정을 공유 달력으로 옮기고, 만료 경보는 당신이 맡겠다고 하세요.',
   '[{"all":["shared calendar"]},{"any":["alert","own","owns"]},{"all":["by friday"]}]',
   'Sam moves the renewals to a shared calendar by Friday, and I''ll own the expiry alert.',
   '["Sam takes the early bus, and I''ll drive.","I''ll have the soup, and Sam wants the burger.","We do laundry on Sunday, and groceries on Monday."]',
   '["Every action item needs a task, a name and a date.","Key words: shared calendar, by Friday, I''ll own"]', '["후속 조치에는 할 일, 이름, 날짜가 모두 있어야 합니다.","핵심 단어: shared calendar, by Friday, I''ll own"]',
   'maya', 'Every item with a name and a date. I like it.', '항목마다 이름과 날짜가 있네요. 마음에 들어요.'),
  ('dk_d8_postmortem', 5, 'maya',
   'One empty heading is left at the bottom of the page.', '보고서 맨 아래에 빈 제목 하나가 남아 있습니다.',
   'Last section. Lessons learned?', 'Say that in hindsight there was a single point of failure, and you were lucky the backup worked: you should not count on luck.', '돌이켜 보면 단일 장애점이 있었고 백업이 동작한 건 운이 좋았던 것이니, 운에 기대면 안 된다고 하세요.',
   '[{"all":["in hindsight"]},{"all":["single point of failure"]},{"all":["count on luck"]}]',
   'In hindsight, we had a single point of failure. We were lucky the backup worked, and we shouldn''t count on luck.',
   '["In the summer, we usually go camping.","I failed my driving test the first time.","The last section of the trail is closed for repairs."]',
   '["Look back honestly: what do you see now that you did not see then?","Key words: in hindsight, single point of failure"]', '["솔직하게 돌아보세요. 그때는 못 봤지만 지금은 보이는 게 무엇인가요?","핵심 단어: in hindsight, single point of failure"]',
   'maya', 'Well said. Send it to the team, and I''ll share a summary with Summit Retail. Let me know if you have any questions.', '잘 말했어요. 팀에 공유해 줘요. 서밋 리테일에는 제가 요약본을 보낼게요. 궁금한 게 있으면 말해 줘요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d8_postmortem.blameless', 'dk_d8_postmortem', 'Let''s keep it blameless.', '누구도 탓하지 않는 방식으로 해요.', 'A blameless postmortem asks "what failed?", not "who failed?", so people speak openly.', 'blameless postmortem은 "누가 잘못했나"가 아니라 "무엇이 잘못됐나"를 물어서 사람들이 솔직하게 말할 수 있게 합니다.', 'meeting'),
  ('dk_d8_postmortem.point_fingers', 'dk_d8_postmortem', 'We''re not here to point fingers.', '손가락질하려고 모인 게 아니에요.', '"Point fingers" = blame people.', 'point fingers는 남을 탓한다는 뜻입니다.', 'meeting'),
  ('dk_d8_postmortem.losing_sleep', 'dk_d8_postmortem', 'I''ve been losing sleep over it.', '그것 때문에 잠을 설쳤어요.', '"Lose sleep over" something = worry about it a lot.', 'lose sleep over는 무언가를 몹시 걱정한다는 뜻입니다.', 'small-talk'),
  ('dk_d8_postmortem.happened_to_anyone', 'dk_d8_postmortem', 'It could have happened to anyone.', '누구에게나 일어날 수 있는 일이었어요.', 'Comforts someone who blames himself for a mistake.', '실수를 자기 탓으로 여기는 사람을 위로하는 말입니다.', 'office'),
  ('dk_d8_postmortem.through_the_cracks', 'dk_d8_postmortem', 'It fell through the cracks.', '(챙기는 사람이 없어) 빠뜨리고 말았어요.', 'Said of a task that was forgotten because nobody was responsible for it.', '책임지는 사람이 없어서 잊힌 일에 대해 씁니다.', 'office'),
  ('dk_d8_postmortem.who_owns_it', 'dk_d8_postmortem', 'Who owns it, and by when?', '누가 맡고, 언제까지 하나요?', '"Own" a task = be the one person responsible for it.', '일을 own한다는 것은 그 일을 책임지는 한 사람이 된다는 뜻입니다.', 'meeting'),
  ('dk_d8_postmortem.in_hindsight', 'dk_d8_postmortem', 'In hindsight, we had a single point of failure.', '돌이켜 보면 단일 장애점이 있었어요.', '"In hindsight" = looking back now. A single point of failure is one part whose failure stops everything.', 'in hindsight는 지금 돌이켜 보면이라는 뜻입니다. single point of failure는 그것 하나가 멈추면 전체가 멈추는 부분입니다.', 'meeting'),
  ('dk_d8_postmortem.lessons_learned', 'dk_d8_postmortem', 'Lessons learned?', '배운 점은요?', 'The last part of a postmortem: what you will do differently next time.', '사후 분석의 마지막 부분으로, 다음에는 무엇을 다르게 할지를 적습니다.', 'meeting');

-- dk_d9_delegate: Letting go of a task

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_delegate', 1, 'jun',
   'Tuesday morning. Rain streaks the office windows. You had already opened the editor to write the certificate alert yourself when you remembered what Maya said about delegating. You walk over to Jun''s desk.', '화요일 아침입니다. 사무실 창문에 빗줄기가 흘러내립니다. 인증서 경보를 직접 만들려고 편집기를 열었다가, 일을 맡기라던 마야의 말이 떠올랐습니다. 준의 자리로 갑니다.',
   'Morning, Derek! Did you need something?', 'Say you have something you would like him to take on: the certificate expiry alert from the postmortem.', '그에게 맡기고 싶은 일이 있다고 하세요. 사후 분석에서 나온 인증서 만료 경보라고요.',
   '[{"all":["take on"]},{"all":["take over"]},{"any":["alert"]}]',
   'I''ve got something I''d like you to take on: the certificate expiry alert from the postmortem.',
   '["I''ve got something in my eye. Do you have a mirror?","I need a ride to the airport on Thursday.","I''d like to take Friday off, if that''s okay."]',
   '["\\"Take on\\" a task = accept it as yours.","Key words: take on, alert"]', '["take on은 일을 자기 것으로 맡는다는 뜻입니다.","핵심 단어: take on, alert"]',
   'jun', 'Me? Sure! But I''ve never touched the monitoring setup.', '저요? 좋아요! 그런데 모니터링 쪽은 한 번도 건드려 본 적이 없어요.'),
  ('dk_d9_delegate', 2, 'jun',
   'Jun opens a new page in his notebook.', '준이 공책의 새 페이지를 폅니다.',
   'What exactly do you need? I don''t want to build the wrong thing.', 'Tell him what done looks like: an alert that fires thirty days before any certificate expires and posts to the on-call channel.', '완료의 기준을 알려 주세요. 인증서가 만료되기 30일 전에 울리고 온콜 채널에 올라오는 경보라고요.',
   '[{"all":["done looks like"]},{"all":["thirty days"]},{"all":["30 days"]},{"any":["fires","expires"]}]',
   'Here''s what done looks like: an alert that fires thirty days before any certificate expires and posts to the on-call channel.',
   '["Here''s what I''d order: the soup and half a sandwich.","It looks like rain, so take an umbrella.","The milk is good for ten more days."]',
   '["Describe the finished result, not the steps.","Key words: what done looks like, fires thirty days before"]', '["과정이 아니라 완성된 결과를 설명하세요.","핵심 단어: what done looks like, fires thirty days before"]',
   'jun', 'Thirty days before, to the on-call channel. That''s clear.', '30일 전에, 온콜 채널로. 분명하네요.'),
  ('dk_d9_delegate', 3, 'jun',
   'He writes it down and underlines it.', '그가 받아 적고 밑줄을 긋습니다.',
   'When do you need it by? I''m flying to Ridgeport on Thursday.', 'Say there is no rush: the end of next week is fine, and the Summit Retail work takes priority.', '급하지 않다고 하세요. 다음 주 말까지면 되고, 서밋 리테일 일이 우선이라고요.',
   '[{"all":["takes priority"]},{"all":["end of next week"]},{"all":["comes first"]},{"any":["priority"]}]',
   'No rush. The end of next week is fine. The Summit Retail work takes priority.',
   '["No rush. The diner is open until nine thirty.","By noon. The fog takes a while to clear.","Gate B12, but boarding is delayed."]',
   '["Give a deadline, and say which of his tasks comes first.","Key words: no rush, end of next week, takes priority"]', '["마감을 알려 주고, 그의 일 가운데 무엇이 먼저인지 말하세요.","핵심 단어: no rush, end of next week, takes priority"]',
   'jun', 'Got it. Trip first, alert second.', '알겠어요. 출장이 먼저, 경보는 그다음.'),
  ('dk_d9_delegate', 4, 'jun',
   'Jun taps his pen on the notebook.', '준이 펜으로 공책을 톡톡 칩니다.',
   'How should I build it? Is there a design you want me to follow?', 'Give him room: how he builds it is his call, and you are here if he hits a wall.', '재량을 주세요. 어떻게 만들지는 그가 정하면 되고, 막히면 당신이 있다고요.',
   '[{"all":["your call"]},{"all":["up to you"]},{"all":["hit a wall"]},{"all":["hits a wall"]}]',
   'How you build it is your call. I''m here if you hit a wall.',
   '["Turn left at the light, and it''s on your right.","Follow the signs to baggage claim.","Build it out of wood. Brick is too expensive."]',
   '["Say the \\"how\\" belongs to him, and that help is there if he needs it.","Key words: your call, hit a wall"]', '["방법은 그가 정할 몫이고, 필요하면 도움을 받을 수 있다고 말하세요.","핵심 단어: your call, hit a wall"]',
   'jun', 'Really? Okay. I''ll sketch something and show you.', '정말요? 알겠어요. 구상을 그려서 보여 드릴게요.'),
  ('dk_d9_delegate', 5, 'jun',
   'He looks a little worried that he will let you down.', '그는 당신을 실망시킬까 봐 조금 걱정하는 눈치입니다.',
   'Should I send you an update every day?', 'Say there is no need for daily updates, and suggest touching base on Wednesday afternoon, before he leaves.', '매일 보고할 필요는 없다고 하고, 그가 떠나기 전 수요일 오후에 잠깐 이야기하자고 제안하세요.',
   '[{"all":["touch base"]},{"all":["touching base"]},{"all":["daily updates"]}]',
   'No need for daily updates. Let''s touch base Wednesday afternoon, before you leave.',
   '["Yes, send it by certified mail.","Every day except Sunday, I think.","I''d charge your phone before the flight."]',
   '["Check in without micromanaging: one short talk, not a daily report.","Key words: no need, touch base"]', '["일일이 간섭하지 않고 살피세요. 매일 보고가 아니라 짧은 대화 한 번이면 됩니다.","핵심 단어: no need, touch base"]',
   'jun', 'Wednesday works. Thanks for trusting me with this, Derek.', '수요일 좋아요. 이 일을 믿고 맡겨 줘서 고마워요, 데릭.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d9_delegate.take_on', 'dk_d9_delegate', 'I''ve got something I''d like you to take on.', '맡아 줬으면 하는 일이 있어요.', '"Take on" = accept a task or responsibility.', 'take on은 일이나 책임을 맡는다는 뜻입니다.', 'office'),
  ('dk_d9_delegate.done_looks_like', 'dk_d9_delegate', 'Here''s what done looks like.', '완료의 기준은 이래요.', 'Describes the finished result, so both people expect the same thing.', '완성된 모습을 설명해서 두 사람이 같은 결과를 기대하게 합니다.', 'office'),
  ('dk_d9_delegate.no_rush', 'dk_d9_delegate', 'No rush.', '급하지 않아요.', 'There is no hurry. Add a date anyway, so "no rush" does not become "never".', '서두를 필요 없다는 뜻입니다. 그래도 날짜를 덧붙여야 "언젠가"가 되지 않습니다.', 'office'),
  ('dk_d9_delegate.takes_priority', 'dk_d9_delegate', 'The Summit Retail work takes priority.', '서밋 리테일 일이 우선이에요.', '"Take priority" = be more important and come first.', 'take priority는 더 중요해서 먼저 한다는 뜻입니다.', 'office'),
  ('dk_d9_delegate.your_call', 'dk_d9_delegate', 'How you build it is your call.', '어떻게 만들지는 당신이 정해요.', '"It''s your call" = you decide. Gives the other person real ownership.', '"It''s your call"은 당신이 결정하라는 뜻입니다. 상대에게 실제 권한을 줍니다.', 'office'),
  ('dk_d9_delegate.hit_a_wall', 'dk_d9_delegate', 'I''m here if you hit a wall.', '막히면 제가 있어요.', '"Hit a wall" = reach a point where you cannot make progress.', 'hit a wall은 더 나아갈 수 없는 지점에 이른다는 뜻입니다.', 'office'),
  ('dk_d9_delegate.touch_base', 'dk_d9_delegate', 'Let''s touch base Wednesday afternoon.', '수요일 오후에 잠깐 이야기해요.', '"Touch base" = talk briefly to share where things are. From baseball.', 'touch base는 상황을 공유하려고 짧게 이야기한다는 뜻입니다. 야구에서 온 말입니다.', 'office'),
  ('dk_d9_delegate.trusting_me_with', 'dk_d9_delegate', 'Thanks for trusting me with this.', '이 일을 믿고 맡겨 줘서 고마워요.', '"Trust someone with" a task = believe they can handle it.', 'trust someone with는 그 사람이 해낼 수 있다고 믿고 맡긴다는 뜻입니다.', 'office');

-- dk_d9_lunch: Ordering in on a rainy day

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_lunch', 1, 'sam',
   'Noon. Rain is hammering the kitchen windows. Sam stands there with an empty mug, looking out at the wet parking lot.', '정오입니다. 비가 탕비실 창문을 세차게 두드립니다. 샘이 빈 머그잔을 들고 젖은 주차장을 내다보고 있습니다.',
   'Look at that. I was going to walk to the taco truck, but no way am I going out in this.', 'Agree, suggest ordering in, and ask if he wants to go in on a pizza.', '맞장구치고, 배달을 시키자고 하고, 같이 돈을 내서 피자를 시키겠냐고 물어보세요.',
   '[{"all":["order in"]},{"all":["ordering in"]},{"all":["go in on"]},{"any":["pizza","delivery"]}]',
   'Me neither. Let''s order in. Want to go in on a pizza?',
   '["Me neither. Let''s take the stairs.","Me too. I walk to work every day.","Let''s go out. It''s beautiful outside."]',
   '["\\"Order in\\" = have food delivered. \\"Go in on\\" = share the cost.","Key words: order in, go in on a pizza"]', '["order in은 음식을 배달시킨다는 뜻이고, go in on은 값을 나눠 낸다는 뜻입니다.","핵심 단어: order in, go in on a pizza"]',
   'sam', 'You read my mind. The place on Lake Avenue delivers.', '제 마음을 읽었네요. 레이크 애비뉴에 있는 가게가 배달해 줘요.'),
  ('dk_d9_lunch', 2, 'sam',
   'Sam opens the menu on his phone.', '샘이 전화기로 메뉴를 엽니다.',
   'What do you want on it? I''m a pepperoni guy.', 'Say you are not picky, suggest half pepperoni and half veggie, and ask them to hold the olives.', '가리는 건 없다고 하고, 반은 페퍼로니, 반은 채소로 하자고 하고, 올리브는 빼 달라고 하세요.',
   '[{"all":["half and half"]},{"all":["not picky"]},{"all":["hold the olives"]},{"all":["half pepperoni"]}]',
   'I''m not picky. How about half and half? Half pepperoni, half veggie. Just hold the olives.',
   '["I''m not sure. How about medium rare?","Half past twelve works for me.","I''d like mine scrambled, with toast."]',
   '["Be easygoing, offer a compromise, and name the one thing you do not want.","Key words: not picky, half and half, hold the olives"]', '["까다롭지 않게, 절충안을 내고, 빼고 싶은 것 하나를 말하세요.","핵심 단어: not picky, half and half, hold the olives"]',
   'sam', 'Half and half, no olives. A large should do it.', '반반에 올리브 빼고. 라지면 충분하겠네요.'),
  ('dk_d9_lunch', 3, 'sam',
   'He adds a large pizza to the cart. The total comes up.', '그가 라지 피자를 장바구니에 담습니다. 합계가 나옵니다.',
   'Okay, it''s twenty-two with tax and delivery, plus the tip. Want to split it?', 'Say sure, split it down the middle, and that you will chip in for the tip, too.', '그러자고, 딱 반씩 나누자고 하고, 팁도 같이 보태겠다고 하세요.',
   '[{"all":["down the middle"]},{"all":["chip in"]},{"any":["split"]}]',
   'Sure, let''s split it down the middle. I''ll chip in for the tip, too.',
   '["Sure, put it on my room.","No, thanks. I already ate.","Sure, I''ll take the window seat."]',
   '["\\"Down the middle\\" = in two equal halves.","Key words: split it down the middle, chip in"]', '["down the middle은 똑같이 둘로 나눈다는 뜻입니다.","핵심 단어: split it down the middle, chip in"]',
   'sam', 'Then it''s thirteen each with a four-dollar tip. Easy.', '그럼 팁 4달러를 넣어서 한 사람에 13달러네요. 간단하죠.'),
  ('dk_d9_lunch', 4, 'sam',
   'Sam pays with his card. You open your wallet and find a single bill.', '샘이 자기 카드로 결제합니다. 지갑을 열어 보니 지폐가 한 장뿐입니다.',
   'I put it on my card. Pay me back whenever.', 'Say all you have on you is a twenty, and ask if he can break it.', '지금 가진 게 20달러짜리 한 장뿐이라고 하고, 거슬러 줄 수 있는지 물어보세요.',
   '[{"all":["break"],"any":["twenty","20","it"]},{"all":["change for"]}]',
   'All I have on me is a twenty. Can you break it?',
   '["All I have is a carry-on.","I need a rest. Let''s get some air.","Can you fix it by Friday?"]',
   '["\\"Break\\" a bill = change it into smaller bills.","Key words: a twenty, break it"]', '["지폐를 break한다는 것은 작은 돈으로 바꾼다는 뜻입니다.","핵심 단어: a twenty, break it"]',
   'sam', 'Let me see. A five and two ones. Here''s seven back.', '어디 봐요. 5달러 한 장에 1달러 두 장. 7달러 거슬러 드릴게요.'),
  ('dk_d9_lunch', 5, 'sam',
   'Half an hour later the pizza is on the kitchen table, and the rain is still falling. Sam lowers his voice.', '30분 뒤 피자가 탕비실 테이블에 놓였고 비는 여전히 내립니다. 샘이 목소리를 낮춥니다.',
   'So, off the record: is the new guy going to survive the Summit Retail project?', 'Say he will be fine: he is sharp, and he is more than holding his own.', '괜찮을 거라고 하세요. 똑똑하고, 제 몫 이상을 거뜬히 해내고 있다고요.',
   '[{"any":["sharp"]},{"all":["holding his own"]},{"all":["be fine"]}]',
   'He''ll be fine. He''s sharp, and he''s more than holding his own.',
   '["He''ll be late. His flight was delayed.","It''s the new one, on the second floor.","He''s allergic to shellfish, I think."]',
   '["Speak well of a teammate who is not in the room.","Key words: sharp, holding his own"]', '["자리에 없는 동료를 좋게 말해 주세요.","핵심 단어: sharp, holding his own"]',
   'sam', 'Good. I like him. He actually reads my emails.', '다행이네요. 저는 그 친구가 좋아요. 제 메일을 진짜로 읽거든요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d9_lunch.order_in', 'dk_d9_lunch', 'Let''s order in.', '배달시켜 먹어요.', '"Order in" = have food delivered instead of going out.', 'order in은 나가지 않고 음식을 배달시킨다는 뜻입니다.', 'food'),
  ('dk_d9_lunch.go_in_on', 'dk_d9_lunch', 'Want to go in on a pizza?', '같이 돈 내서 피자 시킬래요?', '"Go in on" something = buy it together and share the cost.', 'go in on은 함께 사서 값을 나눠 낸다는 뜻입니다.', 'food'),
  ('dk_d9_lunch.not_picky', 'dk_d9_lunch', 'I''m not picky.', '저는 가리는 거 없어요.', '"Picky" = hard to please, especially about food.', 'picky는 특히 음식에 까다롭다는 뜻입니다.', 'food'),
  ('dk_d9_lunch.hold_the_olives', 'dk_d9_lunch', 'Just hold the olives.', '올리브만 빼 주세요.', '"Hold the …" = leave that ingredient out.', '"Hold the …"는 그 재료를 빼 달라는 뜻입니다.', 'food'),
  ('dk_d9_lunch.down_the_middle', 'dk_d9_lunch', 'Let''s split it down the middle.', '딱 반씩 나눠요.', 'Each person pays exactly half.', '각자 정확히 절반씩 낸다는 뜻입니다.', 'money'),
  ('dk_d9_lunch.chip_in', 'dk_d9_lunch', 'I''ll chip in for the tip.', '팁은 저도 보탤게요.', '"Chip in" = give some money toward a shared cost.', 'chip in은 함께 내는 비용에 돈을 보탠다는 뜻입니다.', 'money'),
  ('dk_d9_lunch.break_a_twenty', 'dk_d9_lunch', 'Can you break a twenty?', '20달러짜리 거슬러 줄 수 있어요?', '"A twenty" = a $20 bill. "Break" it = change it into smaller bills.', 'a twenty는 20달러 지폐입니다. break는 작은 지폐로 바꾼다는 뜻입니다.', 'money'),
  ('dk_d9_lunch.off_the_record', 'dk_d9_lunch', 'Off the record …', '여기서만 하는 얘긴데요 …', 'Said before something that should not be repeated to others.', '다른 사람에게 옮기면 안 되는 말을 하기 전에 씁니다.', 'small-talk');

-- dk_d9_review: The reviewer gets reviewed

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_review', 1, 'jun',
   'Jun comes over to your desk with his laptop. His inventory API pull request is ready.', '준이 노트북을 들고 당신 자리로 옵니다. 그의 재고 API 풀 리퀘스트가 준비됐습니다.',
   'Hi, Derek. Do you have a few minutes to review my pull request?', 'Say sure, ask him to send you the link, and to give you twenty minutes.', '그러겠다고 하고, 링크를 보내 달라고, 20분만 달라고 하세요.',
   '[{"all":["send me the link"]},{"all":["twenty minutes"]},{"any":["link"]}]',
   'Sure, send me the link. Give me twenty minutes.',
   '["Sure, send me a postcard from Ridgeport.","Sorry, I''m on vacation until Monday.","Sure, the restroom is down the hall."]',
   '["Say yes, ask for the link, and say how long you need.","Key words: send me the link, twenty minutes"]', '["수락하고, 링크를 달라고 하고, 시간이 얼마나 필요한지 말하세요.","핵심 단어: send me the link, twenty minutes"]',
   'jun', 'Thanks! I looked at yours, too. The gift card one.', '고마워요! 저도 데릭 것을 봤어요. 기프트 카드 풀 리퀘스트요.'),
  ('dk_d9_review', 2, 'jun',
   'Twenty minutes later you have left your comments on his code: good overall, one function that does too much. Now it is your turn, and Jun looks like he is holding something back.', '20분 뒤, 그의 코드에 코멘트를 남겼습니다. 전반적으로 좋고, 함수 하나가 너무 많은 일을 합니다. 이제 당신 차례인데, 준은 뭔가 하고 싶은 말을 참는 눈치입니다.',
   'Yours looks great. Really.', 'Invite honest feedback: tell him not to hold back, and ask if there is anything he would change.', '솔직한 피드백을 청하세요. 망설이지 말라고 하고, 바꾸고 싶은 게 있는지 물어보세요.',
   '[{"all":["hold back"]},{"all":["be honest"]},{"all":["you would change"]}]',
   'Don''t hold back. Be honest: is there anything you''d change?',
   '["Don''t hold the door. I''m taking the stairs.","Hold on. I left my badge in the car.","Could you change a twenty?"]',
   '["A junior may be afraid to criticize a senior. Make it safe.","Key words: don''t hold back, anything you''d change"]', '["후배는 선배를 비판하기 어려워합니다. 편하게 말할 수 있게 해 주세요.","핵심 단어: don''t hold back, anything you''d change"]',
   'jun', 'Well, one small thing. There''s a variable called data2. Last week you told me that was a bad name.', '음, 사소한 거 하나요. data2라는 변수가 있어요. 지난주에 저한테 그건 나쁜 이름이라고 하셨잖아요.'),
  ('dk_d9_review', 3, 'jun',
   'He is right. It was a placeholder, and you forgot about it. Jun watches your face.', '그의 말이 맞습니다. 임시로 붙여 놓고 잊어버린 이름입니다. 준이 당신의 표정을 살핍니다.',
   'Sorry. Is it okay that I said that?', 'Take it graciously: say guilty as charged, that you should practice what you preach, and that you will rename it.', '기분 좋게 받아들이세요. 할 말이 없다고, 말한 대로 실천해야겠다고, 이름을 바꾸겠다고 하세요.',
   '[{"all":["guilty as charged"]},{"all":["practice what i preach"]},{"any":["rename","renaming"]},{"all":["nice catch"]}]',
   'Guilty as charged. I should practice what I preach. I''ll rename it.',
   '["Guilty pleasure: I eat pie for breakfast.","I practice the guitar on weekends.","I''ll charge it to my room."]',
   '["Admit it with a smile, and say what you will do.","Key words: guilty as charged, practice what I preach"]', '["웃으며 인정하고, 어떻게 할지 말하세요.","핵심 단어: guilty as charged, practice what I preach"]',
   'jun', 'Phew. I was nervous about reviewing a senior developer.', '휴. 시니어 개발자를 리뷰하려니 긴장했어요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_review', 4, 'jun',
   'Jun scrolls to his next comment, a little braver now.', '준이 조금 용기를 얻어 다음 코멘트로 내려갑니다.',
   'One more. You call the payment service for the balance every single time. I think we should cache it.', 'Disagree without being defensive: say you see where he is coming from, but a stale balance could let someone spend the same money twice.', '방어적이지 않게 반대하세요. 왜 그렇게 생각하는지는 알겠지만, 오래된 잔액 때문에 같은 돈을 두 번 쓸 수 있다고요.',
   '[{"all":["where you are coming from"]},{"any":["stale"]},{"all":["spend"],"any":["twice"]},{"all":["hold off"]}]',
   'I see where you''re coming from, but I''d hold off on caching. A stale balance could let someone spend the same money twice.',
   '["I see the bus coming. Let''s run!","Where are you from? I grew up in Fairview.","I''d spend the weekend at the beach."]',
   '["Show that you understood his idea before you give your reason.","Key words: I see where you''re coming from, hold off on, stale"]', '["이유를 말하기 전에 그의 생각을 이해했다는 것을 보여 주세요.","핵심 단어: I see where you''re coming from, hold off on, stale"]',
   'jun', 'Oh. I didn''t think about that. Correctness first.', '아. 그건 생각 못 했어요. 정확한 게 먼저군요.'),
  ('dk_d9_review', 5, 'jun',
   'Jun moves his cursor to the "Delete comment" button.', '준이 "코멘트 삭제" 버튼으로 커서를 옮깁니다.',
   'So should I delete my comment?', 'Say no, leave it: it was a fair question, and you are open to changing it if the page gets slow.', '아니라고, 그냥 두라고 하세요. 타당한 질문이었고, 페이지가 느려지면 바꿀 생각도 있다고요.',
   '[{"all":["fair question"]},{"all":["open to"]},{"all":["leave it"]}]',
   'No, leave it. It was a fair question. I''ll add a note explaining why, and I''m open to changing it if the page gets slow.',
   '["No, delete my number, please.","Yes, it opens at nine on weekdays.","No, leave at five to beat the traffic."]',
   '["Respect the question even though you said no to the idea.","Key words: a fair question, open to"]', '["제안은 거절했어도 질문은 존중하세요.","핵심 단어: a fair question, open to"]',
   'jun', 'That makes sense. I learned something today.', '이해됐어요. 오늘 하나 배웠네요.'),
  ('dk_d9_review', 6, 'jun',
   'Jun closes his laptop.', '준이 노트북을 덮습니다.',
   'I''ll split up my function and add the tests, like you said.', 'Thank him for the careful review, and ask if he wants to grab coffee later: you are buying.', '꼼꼼히 리뷰해 줘서 고맙다고 하고, 이따 커피 한잔하겠냐고 물어보세요. 당신이 산다고요.',
   '[{"all":["grab coffee"]},{"all":["grab a coffee"]},{"any":["coffee"]},{"all":["i am buying"]}]',
   'Thanks for the careful review. Want to grab coffee later? I''m buying.',
   '["Thanks, but I already have a library card.","Want to grab an umbrella? It''s pouring.","Thanks for the ride. See you Monday."]',
   '["Thank the reviewer, then make a friendly offer.","Key words: grab coffee, I''m buying"]', '["리뷰어에게 고마움을 전하고, 친근하게 제안하세요.","핵심 단어: grab coffee, I''m buying"]',
   'jun', 'Sure, how about around three?', '좋아요, 세 시쯤 어때요?');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d9_review.dont_hold_back', 'dk_d9_review', 'Don''t hold back.', '망설이지 말고 다 말해요.', '"Hold back" = keep from saying what you really think.', 'hold back은 정말 하고 싶은 말을 참는다는 뜻입니다.', 'office'),
  ('dk_d9_review.guilty_as_charged', 'dk_d9_review', 'Guilty as charged.', '할 말이 없네요. 제 잘못 맞아요.', 'A light, humorous way to admit that a criticism is true. From the courtroom.', '지적이 맞다고 가볍고 재치 있게 인정하는 말입니다. 법정에서 온 표현입니다.', 'office'),
  ('dk_d9_review.practice_what_i_preach', 'dk_d9_review', 'I should practice what I preach.', '말한 대로 저부터 실천해야죠.', 'Do yourself what you tell others to do.', '남에게 하라고 한 것을 자신도 한다는 뜻입니다.', 'office'),
  ('dk_d9_review.coming_from', 'dk_d9_review', 'I see where you''re coming from.', '왜 그렇게 생각하는지 알겠어요.', 'Shows you understand someone''s reasoning, often before you disagree.', '상대의 논리를 이해한다는 말로, 흔히 반대 의견을 내기 전에 씁니다.', 'office'),
  ('dk_d9_review.hold_off_on', 'dk_d9_review', 'I''d hold off on caching.', '캐싱은 미루는 게 좋겠어요.', '"Hold off on" = wait and not do something yet. Softer than "no".', 'hold off on은 아직 하지 않고 기다린다는 뜻입니다. no보다 부드럽습니다.', 'office'),
  ('dk_d9_review.fair_question', 'dk_d9_review', 'It was a fair question.', '타당한 질문이었어요.', 'Tells someone the question was reasonable, even if the answer is no.', '답이 no이더라도 질문 자체는 합당했다고 말해 줍니다.', 'office'),
  ('dk_d9_review.open_to', 'dk_d9_review', 'I''m open to changing it.', '바꿀 생각도 있어요.', '"Open to" = willing to consider. After "to", use a noun or -ing.', 'open to는 고려할 뜻이 있다는 말입니다. to 뒤에는 명사나 -ing가 옵니다.', 'office'),
  ('dk_d9_review.im_buying', 'dk_d9_review', 'I''m buying.', '제가 살게요.', 'You will pay for the drinks or the food.', '음료나 음식값을 내가 내겠다는 뜻입니다.', 'small-talk');

-- dk_d10_stretch: The one-page plan

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d10_stretch', 1, 'maya',
   'Wednesday, cloudy and chilly. You asked Maya for fifteen minutes. The one-page plan she asked for last week is in your hand.', '수요일, 흐리고 쌀쌀합니다. 마야에게 15분을 내 달라고 했습니다. 지난주에 그녀가 말한 한 장짜리 계획이 손에 들려 있습니다.',
   'Come on in, Derek. You wanted to follow up on something?', 'Say you wanted to circle back to your 1:1: you put together the one-page plan she asked for.', '지난 1:1 이야기를 이어서 하고 싶었다고 하세요. 그녀가 말한 한 장짜리 계획을 만들어 왔다고요.',
   '[{"all":["circle back"]},{"all":["one page plan"]},{"all":["put together"]}]',
   'I wanted to circle back to our 1:1. I put together the one-page plan you asked for.',
   '["I wanted to return these. They don''t fit.","I wanted a refill, if it''s not too much trouble.","I put the chairs back in the meeting room."]',
   '["\\"Circle back to\\" = return to a topic you discussed before.","Key words: circle back, one-page plan"]', '["circle back to는 전에 이야기한 주제로 돌아간다는 뜻입니다.","핵심 단어: circle back, one-page plan"]',
   'maya', 'Already? I said next month. I''m impressed.', '벌써요? 다음 달이라고 했는데. 놀랍네요.'),
  ('dk_d10_stretch', 2, 'maya',
   'She reads the page carefully, then looks up.', '그녀가 종이를 꼼꼼히 읽고 고개를 듭니다.',
   'This covers the gift card project. But I also asked you to delegate. How''s that going?', 'Say you took her feedback to heart: you handed the certificate alert to Jun instead of doing it yourself.', '그녀의 피드백을 마음에 새겼다고 하세요. 인증서 경보를 직접 하지 않고 준에게 맡겼다고요.',
   '[{"all":["to heart"]},{"all":["handed"],"any":["jun","alert"]},{"all":["instead of doing it myself"]}]',
   'I took your feedback to heart. I handed the certificate alert to Jun instead of doing it myself.',
   '["I took the bus instead of driving.","I handed in my keys at the front desk.","I know the menu by heart."]',
   '["Show that you acted on the feedback, with a real example.","Key words: took your feedback to heart, handed … to Jun"]', '["실제 사례를 들어 피드백대로 행동했다는 것을 보여 주세요.","핵심 단어: took your feedback to heart, handed … to Jun"]',
   'maya', 'Good. That''s exactly what I wanted to see.', '좋아요. 제가 보고 싶었던 게 바로 그거예요.'),
  ('dk_d10_stretch', 3, 'maya',
   'Maya smiles a little.', '마야가 살짝 웃습니다.',
   'Be honest. Was it hard to let go?', 'Admit it: old habits die hard, and you had to resist the urge to jump in.', '인정하세요. 오랜 습관은 쉽게 안 고쳐지고, 끼어들고 싶은 마음을 참아야 했다고요.',
   '[{"all":["old habits die hard"]},{"all":["resist the urge"]},{"all":["jump in"]}]',
   'Honestly, yes. Old habits die hard. I had to resist the urge to jump in.',
   '["Honestly, no. The mattress was too soft.","Yes, I let the dog out this morning.","Honestly, the traffic was not that bad."]',
   '["Honesty about a struggle builds trust with your manager.","Key words: old habits die hard, resist the urge"]', '["어려웠던 점을 솔직히 말하면 매니저와 신뢰가 쌓입니다.","핵심 단어: old habits die hard, resist the urge"]',
   'maya', 'That urge never goes away completely. You just get better at noticing it.', '그 마음은 완전히 없어지지 않아요. 알아차리는 데 능숙해질 뿐이죠.'),
  ('dk_d10_stretch', 4, 'maya',
   'She puts the page down on her desk.', '그녀가 종이를 책상에 내려놓습니다.',
   'So what''s the ask?', 'Say you would like to step up and own the technical side of the Summit Retail dashboard, with Jun doing most of the building.', '한 단계 더 나서서 서밋 리테일 대시보드의 기술 쪽을 책임지고 싶다고 하세요. 구현은 대부분 준이 하고요.',
   '[{"all":["step up"]},{"all":["technical side"]},{"any":["dashboard"]}]',
   'I''d like to step up and own the technical side of the Summit Retail dashboard, with Jun doing most of the building.',
   '["I''d like to step outside for some air.","I''d like the salad, with the dressing in a cup.","I''d like to own a boat someday."]',
   '["Be specific about the role you are asking for.","Key words: step up, own the technical side"]', '["요청하는 역할을 구체적으로 말하세요.","핵심 단어: step up, own the technical side"]',
   'maya', 'That''s a bigger stage than gift cards. I think you''re ready. Let''s make it official for phase one.', '기프트 카드보다 큰 무대네요. 준비가 된 것 같아요. 1단계부터 공식적으로 그렇게 하죠.'),
  ('dk_d10_stretch', 5, 'maya',
   'Maya opens her calendar.', '마야가 달력을 엽니다.',
   'How will we know it''s working?', 'Propose the next steps: check in every two weeks, and take stock at the end of the quarter.', '다음 단계를 제안하세요. 2주마다 점검하고, 분기 말에 전체를 돌아보자고요.',
   '[{"all":["every two weeks"]},{"all":["take stock"]},{"all":["end of the quarter"]},{"any":["biweekly"]}]',
   'How about we check in every two weeks and take stock at the end of the quarter?',
   '["How about we take the bus and walk back?","I get paid every other Friday.","The quarter is for the parking meter."]',
   '["Offer a rhythm for checking and a date for judging the result.","Key words: every two weeks, take stock, end of the quarter"]', '["점검할 주기와 결과를 평가할 날짜를 제안하세요.","핵심 단어: every two weeks, take stock, end of the quarter"]',
   'maya', 'Every two weeks, and a review at the end of the quarter. I''ll put it in writing. Let me know if you have any questions.', '2주마다, 그리고 분기 말에 평가. 문서로 남겨 둘게요. 궁금한 게 있으면 말해 줘요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d10_stretch.circle_back', 'dk_d10_stretch', 'I wanted to circle back to our 1:1.', '지난 1:1 이야기를 이어서 하고 싶었어요.', '"Circle back (to)" = return to an earlier topic.', 'circle back (to)는 앞서 나눈 주제로 돌아간다는 뜻입니다.', 'office'),
  ('dk_d10_stretch.to_heart', 'dk_d10_stretch', 'I took your feedback to heart.', '피드백을 마음에 새겼어요.', '"Take something to heart" = take it seriously and act on it.', 'take something to heart는 진지하게 받아들이고 행동으로 옮긴다는 뜻입니다.', 'office'),
  ('dk_d10_stretch.let_go', 'dk_d10_stretch', 'Was it hard to let go?', '손에서 놓기 어려웠어요?', '"Let go" = stop holding on; here, stop controlling a task.', 'let go는 붙잡고 있던 것을 놓는다는 뜻으로, 여기서는 일을 직접 통제하지 않는 것입니다.', 'office'),
  ('dk_d10_stretch.old_habits', 'dk_d10_stretch', 'Old habits die hard.', '오랜 습관은 쉽게 안 고쳐져요.', 'A saying: it is difficult to change what you have always done.', '늘 하던 방식은 바꾸기 어렵다는 속담입니다.', 'small-talk'),
  ('dk_d10_stretch.resist_the_urge', 'dk_d10_stretch', 'I had to resist the urge to jump in.', '끼어들고 싶은 마음을 참아야 했어요.', '"Urge" = a strong wish to do something. "Jump in" = get involved suddenly.', 'urge는 하고 싶은 강한 충동입니다. jump in은 갑자기 끼어든다는 뜻입니다.', 'office'),
  ('dk_d10_stretch.whats_the_ask', 'dk_d10_stretch', 'So what''s the ask?', '그래서 요청하는 게 뭐예요?', 'Business English: "the ask" = the thing you are requesting.', '비즈니스 영어에서 the ask는 요청하는 내용을 말합니다.', 'office'),
  ('dk_d10_stretch.step_up', 'dk_d10_stretch', 'I''d like to step up.', '한 단계 더 나서고 싶어요.', '"Step up" = take more responsibility.', 'step up은 더 큰 책임을 맡는다는 뜻입니다.', 'office'),
  ('dk_d10_stretch.take_stock', 'dk_d10_stretch', 'Let''s take stock at the end of the quarter.', '분기 말에 전체를 돌아봐요.', '"Take stock" = stop and judge how things are going. A quarter is three months.', 'take stock은 잠시 멈추고 상황을 평가한다는 뜻입니다. quarter는 석 달입니다.', 'office');

-- dk_d10_handoff: Before you fly

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d10_handoff', 1, 'jun',
   'Wednesday afternoon. Jun flies to Ridgeport tomorrow morning. He stops by your desk with his laptop and a long list.', '수요일 오후입니다. 준은 내일 아침 리지포트로 떠납니다. 그가 노트북과 긴 목록을 들고 당신 자리에 들릅니다.',
   'Could you cover for me on the inventory API while I''m away?', 'Say of course, and ask where things stand right now.', '물론이라고 하고, 지금 상황이 어떤지 물어보세요.',
   '[{"all":["where things stand"]},{"all":["where do things stand"]},{"all":["things stand"]}]',
   'Of course. Where do things stand right now?',
   '["Of course. Where do you keep the coffee filters?","Sorry, I''m away that week, too.","I''d stand in line, but I''m in a hurry."]',
   '["\\"Where do things stand?\\" asks for the current state of the work.","Key words: where do things stand"]', '["\\"Where do things stand?\\"는 일의 현재 상태를 묻는 말입니다.","핵심 단어: where do things stand"]',
   'jun', 'The code is merged, but there''s one open bug. Some store IDs come back empty.', '코드는 머지됐는데, 버그가 하나 남아 있어요. 일부 매장 ID가 빈 값으로 와요.'),
  ('dk_d10_handoff', 2, 'jun',
   'Jun turns his laptop toward you. The ticket is open.', '준이 노트북을 당신 쪽으로 돌립니다. 티켓이 열려 있습니다.',
   'I wrote down everything I know about the bug.', 'Ask what is done and what is left, so that you are both on the same page.', '서로 같은 내용을 알고 있도록, 무엇이 끝났고 무엇이 남았는지 물어보세요.',
   '[{"all":["what is left"]},{"all":["same page"]},{"all":["left to do"]}]',
   'Just so we''re on the same page: what''s done, and what''s left?',
   '["Which page has the dessert menu?","I left my umbrella on the bus.","Is there any pie left?"]',
   '["Split the work into finished and unfinished.","Key words: on the same page, what''s done, what''s left"]', '["일을 끝난 것과 남은 것으로 나누어 물어보세요.","핵심 단어: on the same page, what''s done, what''s left"]',
   'jun', 'Done: I can reproduce it. Left: finding out why. It only happens with some of the stores.', '끝난 것은 버그를 재현할 수 있다는 거예요. 남은 것은 원인 찾기예요. 일부 매장에서만 일어나요.'),
  ('dk_d10_handoff', 3, 'jun',
   'You skim the ticket. It is detailed, but something is missing.', '티켓을 훑어봅니다. 자세하지만 빠진 게 있습니다.',
   'It''s all in the ticket. Well, most of it.', 'Ask where the docs live, and whether there is anything that is only in his head.', '문서가 어디에 있는지, 그리고 그의 머릿속에만 있는 내용이 있는지 물어보세요.',
   '[{"any":["docs","documentation","documented"]},{"all":["in your head"]},{"all":["written down"]}]',
   'Where do the docs live? And is there anything that''s only in your head?',
   '["Where do you live? Near the park?","Is there a drugstore around here?","My head hurts. Do you have any aspirin?"]',
   '["The riskiest knowledge is the kind nobody wrote down.","Key words: where do the docs live, only in your head"]', '["가장 위험한 지식은 아무도 적어 두지 않은 것입니다.","핵심 단어: where do the docs live, only in your head"]',
   'jun', 'Good question. The test data is on my laptop. I''ll upload it to the shared drive before I go.', '좋은 질문이에요. 테스트 데이터가 제 노트북에 있어요. 가기 전에 공유 드라이브에 올릴게요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d10_handoff', 4, 'jun',
   'He adds "upload test data" to his list.', '그가 목록에 "테스트 데이터 올리기"를 추가합니다.',
   'Summit Retail''s IT team might write to you, too.', 'Ask who your point of contact is at Summit Retail, in case something comes up.', '무슨 일이 생길 때를 대비해 서밋 리테일 쪽 담당자가 누구인지 물어보세요.',
   '[{"all":["point of contact"]},{"any":["contact"]},{"all":["reach out to"]}]',
   'Who''s my point of contact at Summit Retail if something comes up?',
   '["Who''s your dentist? I need a new one.","Who''s picking up the check?","Who''s driving to the barbecue on Saturday?"]',
   '["Ask for one name on the client''s side.","Key words: point of contact, if something comes up"]', '["고객사 쪽 사람 한 명의 이름을 물어보세요.","핵심 단어: point of contact, if something comes up"]',
   'jun', 'Greg''s IT lead. Her name is Dana. Her email is in the ticket, and Priya knows her, too.', '그렉 팀의 IT 책임자예요. 이름은 데이나고요. 메일 주소는 티켓에 있고, 프리야도 그분을 알아요.'),
  ('dk_d10_handoff', 5, 'jun',
   'Jun checks his itinerary.', '준이 출장 일정을 확인합니다.',
   'I''ll be reachable on chat if anything comes up.', 'Say you will only call if it is urgent, ask what the best way to reach him is, and say anything else can wait until Monday.', '급할 때만 전화하겠다고 하고, 연락하기 가장 좋은 방법을 묻고, 나머지는 월요일까지 기다려도 된다고 하세요.',
   '[{"all":["best way to reach"]},{"any":["urgent"]},{"all":["can wait"]}]',
   'I''ll only call if it''s urgent. What''s the best way to reach you? Anything else can wait until Monday.',
   '["What''s the best way to the airport from here?","I can''t wait for the weekend.","It''s an emergency exit. Keep it clear."]',
   '["Promise to respect his time on the trip.","Key words: urgent, best way to reach you, can wait"]', '["출장 중인 그의 시간을 존중하겠다고 약속하세요.","핵심 단어: urgent, best way to reach you, can wait"]',
   'jun', 'Chat is best. If it''s urgent, call my cell. I''ll be in meetings with Greg from two o''clock.', '채팅이 제일 좋아요. 급하면 휴대전화로 전화 주세요. 두 시부터는 그렉과 회의예요.'),
  ('dk_d10_handoff', 6, 'jun',
   'He hesitates before he goes.', '그가 가려다 말고 머뭇거립니다.',
   'One more thing. The alert you gave me is only half done. There''s a draft pull request. Do you want to finish it?', 'Resist the urge: say it is all his and you will leave it for him, and wish him safe travels.', '끼어들고 싶은 마음을 참으세요. 그 일은 그의 것이니 그대로 두겠다고 하고, 잘 다녀오라고 하세요.',
   '[{"all":["leave it for you"]},{"all":["safe travels"]},{"all":["all yours"]},{"all":["safe trip"]}]',
   'No, it''s all yours. I''ll leave it for you. Safe travels, and don''t let Greg push you around.',
   '["No, I''ll leave it at the front desk.","Yes, I''d like a wake-up call at six.","No, I''m all out of quarters."]',
   '["Do not take the task back. It can wait for him.","Key words: all yours, leave it for you, safe travels"]', '["일을 도로 가져오지 마세요. 그가 돌아올 때까지 기다려도 됩니다.","핵심 단어: all yours, leave it for you, safe travels"]',
   'jun', 'Ha! I won''t. Thanks, Derek. See you Monday!', '하하! 안 그럴게요. 고마워요, 데릭. 월요일에 봬요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d10_handoff.things_stand', 'dk_d10_handoff', 'Where do things stand right now?', '지금 상황이 어때요?', 'Asks for the current state of a piece of work.', '일의 현재 상태를 묻는 말입니다.', 'office'),
  ('dk_d10_handoff.same_page', 'dk_d10_handoff', 'Just so we''re on the same page …', '서로 같은 내용으로 알고 있도록 …', '"On the same page" = having the same understanding.', 'on the same page는 같은 내용으로 이해하고 있다는 뜻입니다.', 'office'),
  ('dk_d10_handoff.docs_live', 'dk_d10_handoff', 'Where do the docs live?', '문서는 어디에 있어요?', 'In tech talk, files and docs "live" in the place where they are kept.', '개발자들은 파일이나 문서가 보관된 곳을 말할 때 live를 씁니다.', 'office'),
  ('dk_d10_handoff.in_your_head', 'dk_d10_handoff', 'Is there anything that''s only in your head?', '머릿속에만 있는 내용이 있어요?', 'Knowledge that is not written down anywhere. A key handoff question.', '어디에도 적혀 있지 않은 지식을 말합니다. 인수인계의 핵심 질문입니다.', 'office'),
  ('dk_d10_handoff.point_of_contact', 'dk_d10_handoff', 'Who''s my point of contact?', '제가 연락할 담당자가 누구예요?', 'The one person you should talk to at another team or company.', '다른 팀이나 회사에서 내가 이야기해야 할 한 사람입니다.', 'office'),
  ('dk_d10_handoff.comes_up', 'dk_d10_handoff', 'if something comes up', '무슨 일이 생기면', '"Come up" = happen unexpectedly.', 'come up은 예상치 못하게 일이 생긴다는 뜻입니다.', 'office'),
  ('dk_d10_handoff.best_way_to_reach', 'dk_d10_handoff', 'What''s the best way to reach you?', '연락하기 가장 좋은 방법이 뭐예요?', '"Reach" someone = contact them. The answer: chat, email, cell.', 'reach는 연락이 닿는다는 뜻입니다. 대답은 채팅, 메일, 휴대전화 등입니다.', 'office'),
  ('dk_d10_handoff.all_yours', 'dk_d10_handoff', 'It''s all yours.', '전부 당신 몫이에요.', 'You may have it or do it. Here: the task stays with you.', '가져도, 해도 좋다는 뜻입니다. 여기서는 그 일이 계속 당신 것이라는 말입니다.', 'office');

-- dk_d11_call: A quick call to Ridgeport

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d11_call', 1, 'jun',
   'Thursday, a clear day. Jun is in Ridgeport. Priya needs to know by the end of the day which stores have the empty-ID bug, and the list is not in the ticket. You tried chat first. No answer, so you call his cell from your desk.', '목요일, 맑은 날입니다. 준은 리지포트에 있습니다. 프리야는 어느 매장에서 빈 ID 버그가 나는지 오늘 안에 알아야 하는데, 그 목록이 티켓에 없습니다. 먼저 채팅을 보냈지만 답이 없어서, 자리에서 그의 휴대전화로 전화를 겁니다.',
   'Hello, this is Jun.', 'Say it is Derek, apologize for bothering him on the road, and ask if this is a good time.', '데릭이라고 밝히고, 출장 중에 방해해서 미안하다고 하고, 지금 통화 괜찮은지 물어보세요.',
   '[{"all":["good time"]},{"all":["bad time"]},{"all":["sorry to bother"]},{"all":["have a minute"]}]',
   'Hey, Jun, it''s Derek. Sorry to bother you on the road. Is this a good time?',
   '["Hey, Jun, it''s Derek. What time does the diner open?","Hello, I''d like to book a table for two.","Hi, is this the front desk? My key isn''t working."]',
   '["On the phone, say who you are and ask before you start.","Key words: sorry to bother you, is this a good time"]', '["전화에서는 누구인지 밝히고, 용건을 꺼내기 전에 먼저 물어보세요.","핵심 단어: sorry to bother you, is this a good time"]',
   'jun', 'Hi, Derek! Yes, I just checked in at the hotel. I have a few minutes before I head over to Summit Retail.', '안녕하세요, 데릭! 네, 방금 호텔에 체크인했어요. 서밋 리테일로 가기 전에 몇 분 시간이 있어요.'),
  ('dk_d11_call', 2, 'jun',
   'His voice sounds tense.', '그의 목소리가 긴장한 듯합니다.',
   'Is everything okay? Did something break?', 'Reassure him that nothing is on fire, and say you will keep it short: you have one quick question.', '급한 불이 난 건 아니라고 안심시키고, 짧게 끝내겠다고 하세요. 간단한 질문 하나라고요.',
   '[{"all":["on fire"]},{"all":["keep it short"]},{"all":["keep this short"]},{"all":["quick question"]}]',
   'Nothing''s on fire. I''ll keep it short. I just have one quick question.',
   '["Nothing for me, thanks. I''m just browsing.","Yes, the fire alarm went off at noon.","Everything is half price this week."]',
   '["Calm him first, then promise not to take much of his time.","Key words: nothing''s on fire, keep it short"]', '["먼저 안심시키고, 시간을 많이 뺏지 않겠다고 약속하세요.","핵심 단어: nothing''s on fire, keep it short"]',
   'jun', 'Phew. You scared me for a second.', '휴. 잠깐 놀랐어요.'),
  ('dk_d11_call', 3, 'jun',
   'You hear an elevator bell on his end of the line.', '수화기 너머로 엘리베이터 벨 소리가 들립니다.',
   'Okay, what do you need?', 'Ask where the list of affected stores is: you could not find it in the ticket.', '영향을 받는 매장 목록이 어디 있는지 물어보세요. 티켓에서 찾지 못했다고요.',
   '[{"all":["affected stores"]},{"any":["list"]}]',
   'Where''s the list of affected stores? I couldn''t find it in the ticket.',
   '["Where''s the nearest pharmacy? I can''t find my map.","Where''s gate B12? My flight boards soon.","Which stores are open on Sunday?"]',
   '["One clear question, with the reason you are asking.","Key words: the list of affected stores"]', '["묻는 이유를 곁들여 분명한 질문 하나만 하세요.","핵심 단어: the list of affected stores"]',
   'jun', 'Oh no, I forgot to attach it. It''s a spreadsheet on the shared drive, in the folder called "inventory-bugs". Seven stores.', '아, 첨부하는 걸 깜빡했어요. 공유 드라이브의 "inventory-bugs" 폴더에 있는 스프레드시트예요. 매장 일곱 곳이에요.'),
  ('dk_d11_call', 4, 'jun',
   'You find the spreadsheet while he is still talking.', '그가 말하는 동안 스프레드시트를 찾았습니다.',
   'I''m so sorry. I should have put it in the ticket. Do you want me to look at the bug tonight?', 'Say no worries, that is all you needed: he should focus on the client, and you will take it from here.', '괜찮다고, 필요한 건 그게 전부였다고 하세요. 그는 고객에게 집중하고, 여기서부터는 당신이 맡겠다고요.',
   '[{"all":["take it from here"]},{"all":["all i needed"]},{"all":["focus on"]}]',
   'No worries, that''s all I needed. You focus on the client. I''ll take it from here.',
   '["No worries. Take the elevator to the third floor.","That''s all I can eat. I''m full.","Hold the camera still, and I''ll smile."]',
   '["Do not let him work at night on a business trip.","Key words: that''s all I needed, take it from here"]', '["출장 중에 밤까지 일하게 두지 마세요.","핵심 단어: that''s all I needed, take it from here"]',
   'jun', 'Thank you. That''s a weight off my mind.', '고마워요. 마음이 한결 놓이네요.'),
  ('dk_d11_call', 5, 'jun',
   'It is almost time for him to go.', '그가 나가야 할 시간이 다 됐습니다.',
   'I''m meeting Greg in person at two. Any advice?', 'Tell him he has got this and to just be himself, and say you will let him go.', '충분히 해낼 수 있으니 평소대로만 하라고 하고, 이만 끊겠다고 하세요.',
   '[{"all":["got this"]},{"all":["let you go"]},{"all":["be yourself"]}]',
   'You''ve got this. Just be yourself. Anyway, I''ll let you go. Good luck!',
   '["You''ve got mail. Check the front desk.","Let me go first. I''m in a hurry.","You''ve got the wrong number, sorry."]',
   '["\\"I''ll let you go\\" is the polite way to end a call.","Key words: you''ve got this, I''ll let you go"]', '["\\"I''ll let you go\\"는 통화를 정중하게 끝내는 말입니다.","핵심 단어: you''ve got this, I''ll let you go"]',
   'jun', 'Thanks, Derek. I''ll message you after the meeting. Bye!', '고마워요, 데릭. 회의 끝나고 메시지 보낼게요. 끊을게요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d11_call.sorry_to_bother', 'dk_d11_call', 'Sorry to bother you on the road.', '출장 중에 방해해서 미안해요.', '"On the road" = traveling, especially for work.', 'on the road는 특히 일 때문에 이동 중이라는 뜻입니다.', 'office'),
  ('dk_d11_call.good_time', 'dk_d11_call', 'Is this a good time?', '지금 통화 괜찮아요?', 'Ask this at the start of a call. If not: "Did I catch you at a bad time?"', '통화를 시작할 때 묻습니다. 바빠 보이면 "Did I catch you at a bad time?"이라고 합니다.', 'office'),
  ('dk_d11_call.nothing_on_fire', 'dk_d11_call', 'Nothing''s on fire.', '급한 불이 난 건 아니에요.', 'Office slang: there is no emergency.', '직장에서 쓰는 속어로, 비상 상황이 아니라는 뜻입니다.', 'office'),
  ('dk_d11_call.keep_it_short', 'dk_d11_call', 'I''ll keep it short.', '짧게 끝낼게요.', 'A promise not to take much of someone''s time.', '상대의 시간을 많이 뺏지 않겠다는 약속입니다.', 'office'),
  ('dk_d11_call.all_i_needed', 'dk_d11_call', 'That''s all I needed.', '필요한 건 그게 전부였어요.', 'Tells the other person the question is answered and they are free.', '질문이 해결됐으니 이제 가 봐도 된다고 알려 주는 말입니다.', 'office'),
  ('dk_d11_call.take_it_from_here', 'dk_d11_call', 'I''ll take it from here.', '여기서부터는 제가 맡을게요.', 'You will continue the work that someone else started.', '다른 사람이 시작한 일을 이어받아 계속하겠다는 뜻입니다.', 'office'),
  ('dk_d11_call.youve_got_this', 'dk_d11_call', 'You''ve got this.', '충분히 해낼 수 있어요.', 'Encouragement before something difficult.', '어려운 일을 앞둔 사람을 격려하는 말입니다.', 'small-talk'),
  ('dk_d11_call.let_you_go', 'dk_d11_call', 'I''ll let you go.', '이만 끊을게요.', 'A polite way to end a phone call: it sounds like you are freeing the other person.', '통화를 정중하게 끝내는 말입니다. 상대를 놓아준다는 느낌을 줍니다.', 'office');

-- dk_d11_unblock: An answer Priya can forward

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d11_unblock', 1, 'priya',
   'Priya is typing fast. An email from Dana, the IT lead at Summit Retail, is open on her screen.', '프리야가 빠르게 타자를 치고 있습니다. 화면에는 서밋 리테일 IT 책임자 데이나의 메일이 열려 있습니다.',
   'Derek, thank goodness. Dana wants to know which stores have the empty-ID bug, and I''m stuck. Jun''s not answering his chat.', 'Say you just got off the phone with him: it is seven stores, all of which opened this year.', '방금 그와 통화를 마쳤다고 하세요. 매장 일곱 곳이고, 모두 올해 문을 연 곳이라고요.',
   '[{"all":["got off the phone"]},{"all":["seven stores"]},{"all":["7 stores"]},{"all":["opened this year"]}]',
   'I just got off the phone with him. It''s seven stores, all of which opened this year.',
   '["I just got off the bus. It was packed.","It''s seven dollars, plus tax.","I just got back from vacation. It was great."]',
   '["Give the fact and where you got it.","Key words: got off the phone, seven stores"]', '["사실과 그 출처를 함께 말하세요.","핵심 단어: got off the phone, seven stores"]',
   'priya', 'You called him? You''re a lifesaver.', '전화했어요? 덕분에 살았어요.'),
  ('dk_d11_unblock', 2, 'priya',
   'You looked at the seven stores before you came over, and the pattern jumped out at you.', '오기 전에 그 일곱 매장을 살펴봤더니 공통점이 바로 눈에 들어왔습니다.',
   'Dana also asks why it happens. Keep it simple, please. I have to explain it to Greg.', 'Explain it in plain English: the new stores have a longer ID, and the old system cuts it off.', '쉬운 말로 설명하세요. 새 매장들은 ID가 더 길고, 옛 시스템이 그걸 잘라 버린다고요.',
   '[{"all":["plain english"]},{"all":["cuts it off"]},{"all":["longer id"]}]',
   'In plain English: the new stores have a longer ID, and the old system cuts it off.',
   '["The new stores have longer hours on weekends.","I''d like it plain, with nothing on it.","My English teacher was from Ridgeport."]',
   '["No jargon. Say it so a manager can repeat it.","Key words: in plain English, a longer ID, cuts it off"]', '["전문 용어 없이, 관리자가 그대로 옮길 수 있게 말하세요.","핵심 단어: in plain English, a longer ID, cuts it off"]',
   'priya', 'A longer ID that gets cut off. Even I understand that.', '긴 ID가 잘린다. 그건 저도 이해되네요.'),
  ('dk_d11_unblock', 3, 'priya',
   'She starts typing her reply to Dana, then stops.', '그녀가 데이나에게 답장을 쓰기 시작하다가 멈춥니다.',
   'Is it safe to tell her it''ll be fixed by Monday?', 'Do not overpromise: say the fix looks simple, but there is one caveat, you need real data from those stores to test it, so Wednesday, to be safe.', '무리한 약속은 하지 마세요. 수정은 간단해 보이지만 단서가 하나 있다고, 테스트하려면 그 매장들의 실제 데이터가 필요하니 넉넉잡아 수요일로 하자고 하세요.',
   '[{"any":["caveat"]},{"all":["would not promise"]},{"any":["overpromise"]},{"all":["to be safe"]}]',
   'I wouldn''t promise Monday. The fix looks simple, but there''s one caveat: we need real data from those stores to test it. Let''s say Wednesday, to be safe.',
   '["I wouldn''t order the fish on a Monday.","It''s safe to swim here, but the water is cold.","The safe is behind the front desk."]',
   '["Give a date you can keep, and say what it depends on.","Key words: I wouldn''t promise, one caveat, to be safe"]', '["지킬 수 있는 날짜를 말하고, 무엇에 달렸는지 밝히세요.","핵심 단어: I wouldn''t promise, one caveat, to be safe"]',
   'priya', 'Under-promise and over-deliver. Wednesday it is.', '약속은 적게, 결과는 그 이상으로. 수요일로 하죠.'),
  ('dk_d11_unblock', 4, 'priya',
   'Priya looks at the clock. She has another meeting in fifteen minutes.', '프리야가 시계를 봅니다. 15분 뒤에 다른 회의가 있습니다.',
   'Can you write that up for me? Two or three sentences.', 'Say you will send her a short summary in ten minutes, and that she should feel free to forward it as is.', '10분 안에 짧은 요약을 보내겠다고 하고, 그대로 전달해도 된다고 하세요.',
   '[{"all":["as is"]},{"any":["summary"]},{"all":["feel free"]}]',
   'I''ll send you a short summary in ten minutes. Feel free to forward it as is.',
   '["I''ll send you a postcard from the beach.","I''ll write you a check for the deposit.","Two or three scoops, in a cone."]',
   '["Save her time: write it so she does not have to rewrite it.","Key words: a short summary, feel free, as is"]', '["그녀의 시간을 아껴 주세요. 고쳐 쓸 필요가 없게 써 주세요.","핵심 단어: a short summary, feel free, as is"]',
   'priya', 'Perfect. And copy Jun, so he''s in the loop when he gets back.', '완벽해요. 준도 참조에 넣어 줘요. 돌아왔을 때 상황을 알 수 있게요.'),
  ('dk_d11_unblock', 5, 'priya',
   'She picks up her laptop to go.', '그녀가 가려고 노트북을 집어 듭니다.',
   'One last thing. If Dana wants to talk it through tomorrow, would you join?', 'Say sure, you can hop on a call, ask her to loop you in on the email thread, and say you are free any time after ten.', '그럼요, 통화에 들어갈 수 있다고 하고, 메일 스레드에 넣어 달라고 하고, 열 시 이후에는 언제든 된다고 하세요.',
   '[{"all":["hop on"]},{"all":["loop me in"]},{"all":["jump on"]}]',
   'Sure, I can hop on a call. Just loop me in on the email thread. I''m free any time after ten.',
   '["Sure, I can pick you up after ten.","No, I''m not free until the weekend.","Just drop me off at the corner."]',
   '["Offer to join, and ask to be included in the emails.","Key words: hop on a call, loop me in"]', '["참여하겠다고 하고, 메일에 넣어 달라고 부탁하세요.","핵심 단어: hop on a call, loop me in"]',
   'priya', 'Done. You really kept things moving today. I''ll make sure Maya knows.', '그렇게 할게요. 오늘 덕분에 일이 멈추지 않았어요. 마야도 꼭 알게 할게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d11_unblock.got_off_the_phone', 'dk_d11_unblock', 'I just got off the phone with him.', '방금 그와 통화를 마쳤어요.', '"Get off the phone" = finish a call.', 'get off the phone은 통화를 끝낸다는 뜻입니다.', 'office'),
  ('dk_d11_unblock.lifesaver', 'dk_d11_unblock', 'You''re a lifesaver.', '덕분에 살았어요.', 'Warm thanks to someone who got you out of a difficult spot.', '곤란한 상황에서 구해 준 사람에게 하는 따뜻한 감사 표현입니다.', 'small-talk'),
  ('dk_d11_unblock.plain_english', 'dk_d11_unblock', 'In plain English …', '쉬운 말로 하면 …', 'Without technical words, so that anyone can understand.', '전문 용어 없이 누구나 알 수 있게 말한다는 뜻입니다.', 'meeting'),
  ('dk_d11_unblock.caveat', 'dk_d11_unblock', 'There''s one caveat.', '단서가 하나 있어요.', 'A caveat is a warning or condition that limits what you just said.', 'caveat은 방금 한 말에 붙는 주의 사항이나 조건입니다.', 'meeting'),
  ('dk_d11_unblock.to_be_safe', 'dk_d11_unblock', 'Let''s say Wednesday, to be safe.', '넉넉잡아 수요일로 하죠.', '"To be safe" = to leave some room in case of problems.', 'to be safe는 문제가 생길 때를 대비해 여유를 둔다는 뜻입니다.', 'meeting'),
  ('dk_d11_unblock.under_promise', 'dk_d11_unblock', 'Under-promise and over-deliver.', '약속은 적게, 결과는 그 이상으로.', 'A business saying: promise less than you think you can do, then do more.', '할 수 있다고 생각하는 것보다 적게 약속하고 더 많이 해내라는 비즈니스 격언입니다.', 'meeting'),
  ('dk_d11_unblock.as_is', 'dk_d11_unblock', 'Feel free to forward it as is.', '그대로 전달하셔도 돼요.', '"As is" = without any changes. "Feel free to" = you are welcome to.', 'as is는 아무것도 바꾸지 않고라는 뜻입니다. feel free to는 마음껏 해도 된다는 말입니다.', 'office'),
  ('dk_d11_unblock.hop_on_a_call', 'dk_d11_unblock', 'I can hop on a call.', '통화에 들어갈 수 있어요.', '"Hop on" = join quickly and easily. "Loop me in" = include me in the messages.', 'hop on은 가볍게 바로 참여한다는 뜻입니다. loop me in은 연락에 나도 넣어 달라는 말입니다.', 'office');

-- dk_d12_panel: On the interview panel

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d12_panel', 1, 'linda',
   'Friday morning, partly sunny. Linda has three resumes spread out on her desk.', '금요일 아침, 구름 사이로 해가 납니다. 린다의 책상에 이력서 세 장이 펼쳐져 있습니다.',
   'Derek, thanks for stopping by. We''re hiring a backend developer, and I''d like you on the interview panel next week. Can I count on you?', 'Say you would be glad to sit in, ask which days, and say you will block off your calendar.', '기꺼이 들어가겠다고 하고, 무슨 요일인지 묻고, 달력에 시간을 비워 두겠다고 하세요.',
   '[{"all":["block off"]},{"all":["sit in"]},{"all":["which days"]}]',
   'I''d be glad to sit in. Which days? I''ll block off my calendar.',
   '["I''d be glad to sit by the window.","Which bus goes to the airport?","I''ll knock off early and beat the traffic."]',
   '["Say yes, then ask for the dates so you can keep them free.","Key words: sit in, which days, block off"]', '["수락하고, 시간을 비워 둘 수 있게 날짜를 물어보세요.","핵심 단어: sit in, which days, block off"]',
   'linda', 'Tuesday and Thursday afternoon. Three candidates, forty-five minutes each.', '화요일과 목요일 오후예요. 지원자 세 명, 한 명에 45분씩이에요.'),
  ('dk_d12_panel', 2, 'linda',
   'She hands you a blank scorecard.', '그녀가 빈 평가표를 건넵니다.',
   'You''ll run the technical part. What will you be looking for?', 'Say you care less about trick questions and more about how they think, so you will have them talk you through a real problem.', '함정 문제보다 어떻게 생각하는지가 더 중요하니, 실제 문제를 말로 풀어 보게 하겠다고 하세요.',
   '[{"all":["how they think"]},{"all":["talk me through"]},{"all":["trick questions"]}]',
   'I care less about trick questions and more about how they think. I''ll have them talk me through a real problem.',
   '["I''m looking for aisle seven. Is it this way?","I''m looking for my keys. Have you seen them?","I think they closed the pool for the season."]',
   '["Say what matters to you, and how you will find it out.","Key words: how they think, talk me through"]', '["무엇을 중요하게 보는지, 그것을 어떻게 알아낼지 말하세요.","핵심 단어: how they think, talk me through"]',
   'linda', 'Good. That''s what the scorecard is for. Same questions for everyone, so it''s fair.', '좋아요. 평가표가 그래서 있는 거예요. 공정하도록 모두에게 같은 질문을 하는 거죠.'),
  ('dk_d12_panel', 3, 'linda',
   'Linda picks up her pen.', '린다가 펜을 듭니다.',
   'And what''s a red flag for you?', 'Say it is someone who takes all the credit, or throws their old team under the bus.', '공을 혼자 다 차지하거나, 전 직장 팀에 책임을 떠넘기는 사람이라고 하세요.',
   '[{"all":["under the bus"]},{"all":["all the credit"]},{"any":["blames","blaming"]}]',
   'Someone who takes all the credit, or throws their old team under the bus.',
   '["Someone who takes the last donut.","The red one, next to the lifeguard tower.","The Number 12, from the stop on Maple Street."]',
   '["A red flag is a warning sign. Name a behavior, not a skill.","Key words: all the credit, under the bus"]', '["red flag는 위험 신호입니다. 기술이 아니라 행동을 말하세요.","핵심 단어: all the credit, under the bus"]',
   'linda', 'Agreed. How people talk about their last team tells you a lot.', '동의해요. 전 팀을 어떻게 말하는지 보면 많은 걸 알 수 있죠.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d12_panel', 4, 'linda',
   'She becomes more serious.', '그녀의 표정이 진지해집니다.',
   'Now, my part. Small talk is fine, but there are questions we can''t ask. Do you know where the line is?', 'Say you will steer clear of anything personal, like age, family, or where someone is from, and stick to the job.', '나이, 가족, 출신처럼 사적인 것은 피하고, 업무 이야기만 하겠다고 하세요.',
   '[{"all":["steer clear"]},{"all":["stick to"]},{"any":["personal"]}]',
   'I''ll steer clear of anything personal, like age, family, or where someone is from, and stick to the job.',
   '["I''ll steer the cart. You grab the milk.","The line is at the food truck. It''s long today.","I''m from Fairview. Born and raised."]',
   '["In a US interview, questions about age, family, religion or origin are off-limits.","Key words: steer clear of, anything personal, stick to the job"]', '["미국 면접에서는 나이, 가족, 종교, 출신에 대한 질문이 금지입니다.","핵심 단어: steer clear of, anything personal, stick to the job"]',
   'linda', 'Exactly. Even "Are you married?" as small talk is off-limits. When in doubt, don''t ask.', '바로 그거예요. 가벼운 잡담으로 "결혼하셨어요?"라고 묻는 것도 금지예요. 애매하면 묻지 마세요.'),
  ('dk_d12_panel', 5, 'linda',
   'She writes your name on the panel list.', '그녀가 면접관 명단에 당신의 이름을 적습니다.',
   'One more thing. Please write down your feedback before we debrief, not after.', 'Say that makes sense: that way, nobody gets swayed by the loudest voice in the room.', '일리가 있다고 하세요. 그래야 목소리 큰 사람의 의견에 아무도 휩쓸리지 않는다고요.',
   '[{"any":["swayed","sway"]},{"all":["loudest voice"]},{"all":["makes sense"]}]',
   'That makes sense. That way, nobody gets swayed by the loudest voice in the room.',
   '["That way, and then left at the fountain.","The room comes with a view of the ocean.","Nobody told me the pool was closed."]',
   '["Agree, and show that you understand the reason for the rule.","Key words: makes sense, swayed, the loudest voice"]', '["동의하고, 그 규칙의 이유를 이해한다는 것을 보여 주세요.","핵심 단어: makes sense, swayed, the loudest voice"]',
   'linda', 'You''ve done this before. I''ll send the invites today.', '해 보신 분이네요. 오늘 초대장을 보낼게요.'),
  ('dk_d12_panel', 6, 'linda',
   'You have a question of your own for HR.', '인사팀에 물어볼 것이 하나 있습니다.',
   'Anything else I can help you with while you''re here?', 'Say you were on call all last week, including the weekend, and ask if you are entitled to any comp time.', '지난주 내내 주말까지 온콜이었다고 하고, 보상 휴가를 받을 수 있는지 물어보세요.',
   '[{"all":["comp time"]},{"any":["entitled"]},{"all":["time off"]},{"all":["day off"]}]',
   'Actually, yes. I was on call all last week, including the weekend. Am I entitled to any comp time?',
   '["Actually, yes. Where do I park my bike?","Actually, I''d like a table near the window.","Yes, what time does the market close?"]',
   '["\\"Comp time\\" = paid time off that you get in return for extra hours.","Key words: on call, entitled to, comp time"]', '["comp time은 추가로 일한 시간에 대해 받는 유급 휴가입니다.","핵심 단어: on call, entitled to, comp time"]',
   'linda', 'You are. A week on call earns you half a day. Put in the request, and Maya will approve it. Just use it within sixty days.', '받을 수 있어요. 온콜 한 주에 반일이 나와요. 신청하면 마야가 승인할 거예요. 60일 안에만 쓰세요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d12_panel.block_off', 'dk_d12_panel', 'I''ll block off my calendar.', '달력에 시간을 비워 둘게요.', '"Block off" time = reserve it so nobody books a meeting then.', 'block off는 다른 회의가 잡히지 않게 시간을 잡아 둔다는 뜻입니다.', 'office'),
  ('dk_d12_panel.talk_me_through', 'dk_d12_panel', 'I''ll have them talk me through a real problem.', '실제 문제를 말로 풀어 보게 할 거예요.', '"Talk someone through" = explain your thinking step by step, out loud.', 'talk someone through는 생각의 과정을 단계별로 소리 내어 설명한다는 뜻입니다.', 'office'),
  ('dk_d12_panel.red_flag', 'dk_d12_panel', 'What''s a red flag for you?', '어떤 게 위험 신호라고 보세요?', 'A red flag is a warning sign that something may be wrong.', 'red flag는 무언가 문제가 있을 수 있다는 경고 신호입니다.', 'office'),
  ('dk_d12_panel.under_the_bus', 'dk_d12_panel', 'throw someone under the bus', '남에게 책임을 떠넘기다', 'Blame another person to protect yourself.', '자신을 지키려고 다른 사람을 탓한다는 뜻입니다.', 'office'),
  ('dk_d12_panel.steer_clear', 'dk_d12_panel', 'I''ll steer clear of anything personal.', '사적인 것은 피할게요.', '"Steer clear of" = stay away from.', 'steer clear of는 멀리한다는 뜻입니다.', 'office'),
  ('dk_d12_panel.off_limits', 'dk_d12_panel', 'That question is off-limits.', '그 질문은 금지예요.', 'Not allowed. In US interviews: age, marriage, children, religion, national origin.', '허용되지 않는다는 뜻입니다. 미국 면접에서는 나이, 결혼, 자녀, 종교, 출신 국가가 해당됩니다.', 'office'),
  ('dk_d12_panel.comp_time', 'dk_d12_panel', 'Am I entitled to any comp time?', '보상 휴가를 받을 수 있나요?', '"Comp time" (compensatory time) = time off for extra hours. "Entitled to" = having the right to.', 'comp time(compensatory time)은 추가 근무에 대한 휴가입니다. entitled to는 받을 권리가 있다는 뜻입니다.', 'hr'),
  ('dk_d12_panel.when_in_doubt', 'dk_d12_panel', 'When in doubt, don''t ask.', '애매하면 묻지 마세요.', '"When in doubt, …" gives a safe rule for cases when you are not sure.', '"When in doubt, …"는 확신이 없을 때 따를 안전한 규칙을 말해 줍니다.', 'office');

-- dk_d12_signed: Good news from Ridgeport

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d12_signed', 1, 'jun',
   'Friday afternoon. Your phone rings at your desk. It is Jun, calling from the airport in Ridgeport.', '금요일 오후입니다. 자리에서 전화가 울립니다. 리지포트 공항에서 준이 건 전화입니다.',
   'Derek! It''s Jun. We signed the contract this morning!', 'Congratulate him: say that is huge, and that he pulled it off.', '축하해 주세요. 정말 큰일을 했다고, 해냈다고요.',
   '[{"any":["congratulations","congrats"]},{"all":["pulled it off"]},{"all":["that is huge"]}]',
   'Congratulations! That''s huge. You pulled it off!',
   '["That''s a shame. Better luck next time.","Happy birthday! How old are you now?","Welcome aboard! Your seat is 14C."]',
   '["Share his joy first. Work can wait a minute.","Key words: congratulations, that''s huge, pulled it off"]', '["먼저 함께 기뻐해 주세요. 일 이야기는 잠시 뒤에 해도 됩니다.","핵심 단어: congratulations, that''s huge, pulled it off"]',
   'jun', 'Thank you! Greg shook my hand. I still can''t believe it.', '감사합니다! 그렉이 악수를 청했어요. 아직도 믿기지 않아요.'),
  ('dk_d12_signed', 2, 'jun',
   'You hear a boarding announcement behind him.', '그의 뒤로 탑승 안내 방송이 들립니다.',
   'But I''ve been worried about the inventory bug. How bad is it?', 'Say it is all taken care of: you tracked down the cause, and the fix is waiting for his review.', '다 처리됐다고 하세요. 원인을 찾아냈고, 수정한 코드가 그의 리뷰를 기다리고 있다고요.',
   '[{"all":["taken care of"]},{"all":["tracked down"]},{"all":["tracked it down"]},{"all":["waiting for your review"]}]',
   'It''s all taken care of. I tracked down the cause, and the fix is waiting for your review.',
   '["It''s pretty bad. I''d see a doctor.","It''s waiting at baggage claim, carousel four.","I tracked my package. It arrives Monday."]',
   '["Report the result, and leave the last step to him: it is his code.","Key words: taken care of, tracked down, waiting for your review"]', '["결과를 알려 주고 마지막 단계는 그에게 남기세요. 그의 코드니까요.","핵심 단어: taken care of, tracked down, waiting for your review"]',
   'jun', 'Already? I owe you one.', '벌써요? 제가 신세 졌네요.'),
  ('dk_d12_signed', 3, 'jun',
   'Jun laughs, then turns suspicious.', '준이 웃다가 의심스러운 목소리로 바뀝니다.',
   'And the alert? You finished that too, didn''t you?', 'Say no, you did not lay a finger on it: it is still his, and it can wait till Monday.', '아니라고, 손끝 하나 대지 않았다고 하세요. 여전히 그의 일이고, 월요일까지 기다려도 된다고요.',
   '[{"all":["lay a finger"]},{"all":["did not touch"]},{"all":["still yours"]}]',
   'Nope. I didn''t lay a finger on it. It''s still yours, and it can wait till Monday.',
   '["Nope. I didn''t order the fish.","Yes, I finished the whole pizza myself.","I cut my finger on the box."]',
   '["You delegated it, so you left it alone. Say so.","Key words: didn''t lay a finger on it, still yours"]', '["맡긴 일이니 건드리지 않았습니다. 그렇게 말하세요.","핵심 단어: didn''t lay a finger on it, still yours"]',
   'jun', 'Good. I want to finish that one myself.', '다행이에요. 그건 제 손으로 끝내고 싶어요.'),
  ('dk_d12_signed', 4, 'jun',
   'He sounds tired but happy.', '그는 지쳤지만 기쁜 목소리입니다.',
   'My flight is overbooked, so I''m taking a later one. I can work on the alert at the gate tonight.', 'Tell him to call it a day: he has earned it, and he should unplug this weekend.', '오늘 일은 여기까지 하라고 하세요. 쉴 자격이 충분하고, 이번 주말에는 일에서 완전히 손을 떼라고요.',
   '[{"all":["call it a day"]},{"any":["unplug"]},{"all":["earned it"]}]',
   'Don''t you dare. Call it a day. You''ve earned it. And unplug this weekend.',
   '["Call a cab. The shuttle just left.","Plug it in behind the desk.","Call me at the hotel after nine."]',
   '["A good lead protects people''s rest.","Key words: call it a day, earned it, unplug"]', '["좋은 리더는 팀원의 휴식을 지켜 줍니다.","핵심 단어: call it a day, earned it, unplug"]',
   'jun', 'Okay, okay. No laptop. I promise.', '알겠어요, 알겠어요. 노트북은 안 열게요. 약속해요.'),
  ('dk_d12_signed', 5, 'jun',
   'The announcement behind him gets louder.', '그의 뒤에서 안내 방송 소리가 커집니다.',
   'Thanks for covering for me, Derek. Really.', 'Say anytime, that is what teammates are for, and that you will see him bright and early on Monday.', '언제든지라고, 팀 동료가 그러라고 있는 거라고 하고, 월요일 아침 일찍 보자고 하세요.',
   '[{"all":["what teammates are for"]},{"all":["bright and early"]},{"all":["what friends are for"]}]',
   'Anytime. That''s what teammates are for. See you bright and early on Monday.',
   '["Thanks. I''ll take two, please.","You''re welcome to try the soup.","See you at the gate. I''m in row twelve."]',
   '["Accept thanks lightly, and say goodbye.","Key words: that''s what teammates are for, bright and early"]', '["고맙다는 말을 가볍게 받고 작별 인사를 하세요.","핵심 단어: that''s what teammates are for, bright and early"]',
   'jun', 'See you Monday! Oh, they''re calling my flight. Bye!', '월요일에 봬요! 아, 제 비행기 탑승 안내가 나와요. 끊을게요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d12_signed.pulled_it_off', 'dk_d12_signed', 'You pulled it off!', '해냈네요!', '"Pull off" = succeed at something difficult.', 'pull off는 어려운 일을 해낸다는 뜻입니다.', 'small-talk'),
  ('dk_d12_signed.thats_huge', 'dk_d12_signed', 'That''s huge.', '정말 큰일을 했네요.', '"Huge" here means very important, great news.', '여기서 huge는 아주 중요하다, 대단한 소식이라는 뜻입니다.', 'small-talk'),
  ('dk_d12_signed.taken_care_of', 'dk_d12_signed', 'It''s all taken care of.', '다 처리됐어요.', 'Everything has been handled, so you do not need to worry.', '모두 처리했으니 걱정할 필요 없다는 뜻입니다.', 'office'),
  ('dk_d12_signed.tracked_down', 'dk_d12_signed', 'I tracked down the cause.', '원인을 찾아냈어요.', '"Track down" = find after searching.', 'track down은 찾아다닌 끝에 찾아낸다는 뜻입니다.', 'office'),
  ('dk_d12_signed.owe_you_one', 'dk_d12_signed', 'I owe you one.', '제가 신세 졌네요.', 'Thanks for a favor, with a promise to return it someday.', '도움에 고마워하며 언젠가 갚겠다고 하는 말입니다.', 'small-talk'),
  ('dk_d12_signed.lay_a_finger', 'dk_d12_signed', 'I didn''t lay a finger on it.', '손끝 하나 대지 않았어요.', '"Not lay a finger on" = not touch at all.', 'not lay a finger on은 전혀 건드리지 않는다는 뜻입니다.', 'office'),
  ('dk_d12_signed.call_it_a_day', 'dk_d12_signed', 'Call it a day.', '오늘은 여기까지 해요.', 'Stop working for today. "Unplug" = stay away from work and screens.', '오늘 일을 그만한다는 뜻입니다. unplug는 일과 화면에서 떨어져 쉰다는 뜻입니다.', 'office'),
  ('dk_d12_signed.bright_and_early', 'dk_d12_signed', 'See you bright and early on Monday.', '월요일 아침 일찍 봐요.', '"Bright and early" = early in the morning, and fresh.', 'bright and early는 아침 일찍, 그리고 상쾌하게라는 뜻입니다.', 'small-talk');

-- dk_w2_mower: The mower comes home

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_mower', 1, 'carl',
   'Saturday, sunny and warm. Carl pulls up in front of your house with your lawn mower in the back of his pickup.', '토요일, 맑고 따뜻합니다. 칼이 픽업트럭 짐칸에 당신의 잔디 깎는 기계를 싣고 집 앞에 차를 댑니다.',
   'Special delivery! She runs like new. It wasn''t the spark plug, by the way. The carburetor was all gummed up.', 'Thank him: say you cannot thank him enough, and that he saved you a trip to the repair shop.', '고마움을 전하세요. 어떻게 감사해야 할지 모르겠다고, 덕분에 수리점에 안 가도 됐다고요.',
   '[{"all":["thank you enough"]},{"all":["saved me a trip"]}]',
   'Carl, I can''t thank you enough. You saved me a trip to the repair shop.',
   '["Carl, I can''t hear you. The mower is too loud.","I can''t make it on Saturday. I''m on call.","Enough for me, thanks. I''m full."]',
   '["A big favor deserves more than \\"thanks\\".","Key words: can''t thank you enough, saved me a trip"]', '["큰 도움에는 thanks보다 더 큰 말이 어울립니다.","핵심 단어: can''t thank you enough, saved me a trip"]',
   'carl', 'Those shops charge ninety bucks just to look at it. Robbery.', '그런 가게는 들여다보기만 해도 90달러를 받아. 날강도지.'),
  ('dk_w2_mower', 2, 'carl',
   'You pull the cord. The engine starts on the first try.', '줄을 당깁니다. 엔진이 한 번에 걸립니다.',
   'Hear that? Purring like a kitten.', 'Ask what you owe him for the parts, and say you insist.', '부품값으로 얼마를 드리면 되는지 묻고, 꼭 내고 싶다고 하세요.',
   '[{"all":["owe you"]},{"any":["insist"]},{"all":["pay you back"]}]',
   'What do I owe you for the parts? I insist.',
   '["What do you recommend for dessert?","What do I need to bring to the airport?","How much is a one-way ticket?"]',
   '["Offer to pay at least for the parts. \\"I insist\\" shows you mean it.","Key words: what do I owe you, I insist"]', '["적어도 부품값은 내겠다고 하세요. \\"I insist\\"는 진심이라는 표시입니다.","핵심 단어: what do I owe you, I insist"]',
   'carl', 'Eleven dollars for a gasket. Keep your money. Buy me a coffee sometime.', '개스킷 하나에 11달러 들었네. 돈은 넣어 두게. 언제 커피나 한 잔 사.'),
  ('dk_w2_mower', 3, 'carl',
   'Carl opens his toolbox on the tailgate.', '칼이 트럭 뒷문 위에 공구함을 엽니다.',
   'Anything else need fixing while I''ve got my tools out?', 'Say now that he mentions it, the gutter over the front door has been leaking since Tuesday, and ask if you can fix it yourself.', '말이 나와서 말인데, 현관 위 빗물받이가 화요일부터 샌다고 하고, 직접 고칠 수 있는 건지 물어보세요.',
   '[{"any":["gutter","leaking","leak","leaks"]},{"all":["now that you mention it"]}]',
   'Now that you mention it, the gutter over the front door has been leaking since Tuesday. Is that something I can fix myself?',
   '["No, thanks. I''m just looking.","My laptop won''t turn on. Can you reset my password?","The elevator is stuck between floors."]',
   '["\\"Now that you mention it\\" introduces something his question reminded you of.","Key words: now that you mention it, gutter, leaking"]', '["\\"Now that you mention it\\"은 상대의 말 덕분에 떠오른 이야기를 꺼낼 때 씁니다.","핵심 단어: now that you mention it, gutter, leaking"]',
   'carl', 'Probably just clogged with leaves. Get a ladder and a pair of gloves. Twenty minutes, tops. I''ll hold the ladder.', '낙엽으로 막혔을 뿐일 걸세. 사다리하고 장갑을 가져오게. 길어야 20분이야. 사다리는 내가 잡아 주지.'),
  ('dk_w2_mower', 4, 'carl',
   'Twenty minutes later the gutter is clear, and your gloves are full of wet leaves.', '20분 뒤 빗물받이가 뚫렸고, 장갑에는 젖은 낙엽이 가득합니다.',
   'You should do this every fall, you know. Before the rain, not after.', 'Admit you keep putting it off, and say you are glad you got to it before tomorrow''s rain.', '자꾸 미뤄 왔다고 인정하고, 내일 비가 오기 전에 해치워서 다행이라고 하세요.',
   '[{"all":["putting it off"]},{"all":["put it off"]},{"all":["got to it"]},{"all":["get around to it"]}]',
   'I know, I keep putting it off. I''m glad we got to it before tomorrow''s rain.',
   '["I know. I keep my keys by the door.","I''ll get off at the next stop.","Put it on my tab, please."]',
   '["\\"Put off\\" = delay something you do not feel like doing.","Key words: keep putting it off, got to it"]', '["put off는 하기 싫은 일을 미룬다는 뜻입니다.","핵심 단어: keep putting it off, got to it"]',
   'carl', 'Just in time. Showers all day tomorrow, the paper says.', '딱 맞춰 했구먼. 신문에 내일은 종일 소나기라더군.'),
  ('dk_w2_mower', 5, 'carl',
   'Carl closes his toolbox and wipes his hands.', '칼이 공구함을 닫고 손을 닦습니다.',
   'Now it''s my turn. I''m grilling at my place today at four. Jun from my building is coming, too. You in?', 'Say you would not miss it, and offer to bring dessert: it is the least you can do.', '꼭 가겠다고 하고, 디저트를 가져가겠다고 하세요. 그 정도는 해야 한다고요.',
   '[{"all":["would not miss it"]},{"all":["least i can do"]},{"any":["dessert"]}]',
   'I wouldn''t miss it. Let me bring dessert. It''s the least I can do.',
   '["I missed it. The bus left without me.","Let me bring the car around.","At least it''s not raining."]',
   '["Accept warmly and return the favor in a small way.","Key words: wouldn''t miss it, the least I can do"]', '["흔쾌히 수락하고 작게나마 보답하세요.","핵심 단어: wouldn''t miss it, the least I can do"]',
   'carl', 'Dessert works. Nothing with raisins. See you at four, Derek!', '디저트 좋지. 건포도 들어간 것만 빼고. 네 시에 보세, 데릭!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_w2_mower.thank_you_enough', 'dk_w2_mower', 'I can''t thank you enough.', '어떻게 감사해야 할지 모르겠어요.', 'Very strong thanks, for a big favor.', '큰 도움을 받았을 때 쓰는 아주 강한 감사 표현입니다.', 'small-talk'),
  ('dk_w2_mower.saved_me_a_trip', 'dk_w2_mower', 'You saved me a trip to the repair shop.', '덕분에 수리점에 안 가도 됐어요.', '"Save someone a trip" = make it unnecessary for them to go somewhere.', 'save someone a trip은 어딘가에 갈 필요가 없게 해 준다는 뜻입니다.', 'small-talk'),
  ('dk_w2_mower.what_do_i_owe', 'dk_w2_mower', 'What do I owe you for the parts?', '부품값으로 얼마 드리면 돼요?', 'A natural way to offer payment to a friend or neighbor.', '친구나 이웃에게 돈을 내겠다고 자연스럽게 말하는 표현입니다.', 'money'),
  ('dk_w2_mower.i_insist', 'dk_w2_mower', 'I insist.', '꼭 그러고 싶어요.', 'Said when someone politely refuses your offer and you really mean it.', '상대가 예의상 사양할 때, 진심이라는 뜻으로 하는 말입니다.', 'small-talk'),
  ('dk_w2_mower.now_that_you_mention', 'dk_w2_mower', 'Now that you mention it …', '말이 나와서 말인데요 …', 'What you said reminded me of something.', '상대의 말을 듣고 무언가 떠올랐을 때 씁니다.', 'small-talk'),
  ('dk_w2_mower.tops', 'dk_w2_mower', 'Twenty minutes, tops.', '길어야 20분이에요.', '"Tops" after a number = at the most. Casual.', '숫자 뒤의 tops는 많아야, 길어야라는 편한 표현입니다.', 'small-talk'),
  ('dk_w2_mower.putting_it_off', 'dk_w2_mower', 'I keep putting it off.', '자꾸 미루게 돼요.', '"Put off" = delay. "Keep …ing" = do again and again.', 'put off는 미룬다는 뜻이고, "keep …ing"는 자꾸 되풀이한다는 뜻입니다.', 'small-talk'),
  ('dk_w2_mower.least_i_can_do', 'dk_w2_mower', 'It''s the least I can do.', '그 정도는 해야죠.', 'Said when you give something small in return for a big favor.', '큰 도움에 작은 것으로 보답할 때 하는 말입니다.', 'small-talk');

-- dk_w2_market: A rain check on the ice cream

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_market', 1, 'mike',
   'Fairview Market on a warm Saturday. This week''s flyer says vanilla ice cream is buy one, get one free, but the shelf in the freezer is empty. You walk up to Mike''s lane.', '따뜻한 토요일의 페어뷰 마켓입니다. 이번 주 전단에는 바닐라 아이스크림이 하나 사면 하나 더라고 되어 있는데, 냉동고 선반이 텅 비어 있습니다. 마이크의 계산대로 갑니다.',
   'Hey, Derek! Back again? Did you find everything okay?', 'Say not quite: the ice cream in the flyer is sold out, and ask if they have any more in the back.', '다 찾지는 못했다고 하세요. 전단에 나온 아이스크림이 다 팔렸다고 하고, 창고에 더 있는지 물어보세요.',
   '[{"all":["sold out"]},{"all":["in the back"]},{"any":["flyer"]}]',
   'Not quite. The ice cream in the flyer is sold out. Do you have any more in the back?',
   '["Not quite. I''m still waiting for my luggage.","Yes, I found a wallet in the parking lot.","My back hurts. Where are the pain relievers?"]',
   '["Say what is missing, and ask about the stockroom.","Key words: sold out, in the back"]', '["없는 물건을 말하고, 창고에 있는지 물어보세요.","핵심 단어: sold out, in the back"]',
   'mike', 'Let me check. Nope, we''re cleaned out. It went fast in this heat.', '확인해 볼게요. 없네요, 싹 다 나갔어요. 날이 더우니 금방 팔렸어요.'),
  ('dk_w2_market', 2, 'mike',
   'Mike puts down the store phone.', '마이크가 매장 전화기를 내려놓습니다.',
   'Sorry about that. The next truck comes on Tuesday.', 'Ask for a rain check, so that you can get the sale price next week.', '다음 주에 할인 가격으로 살 수 있게 레인 체크를 달라고 하세요.',
   '[{"all":["rain check"]},{"any":["raincheck"]},{"all":["sale price"]}]',
   'Could I get a rain check, so I can get the sale price next week?',
   '["Could I get a ride? It looks like rain.","Could I check my bag at the counter?","Could I get change for the parking meter?"]',
   '["Stores give a slip that keeps the sale price for later.","Key words: rain check, sale price"]', '["가게에서는 나중에도 할인 가격으로 살 수 있는 쪽지를 써 줍니다.","핵심 단어: rain check, sale price"]',
   'mike', 'Sure thing. I''ll write you one. It''s good for thirty days.', '그럼요. 하나 써 드릴게요. 30일 동안 쓸 수 있어요.'),
  ('dk_w2_market', 3, 'mike',
   'He takes a pad of slips from under the register.', '그가 계산대 아래에서 쪽지 묶음을 꺼냅니다.',
   'How many do you want on it? There''s a limit of two deals per customer.', 'Ask him to put you down for two, then.', '그럼 두 개로 적어 달라고 하세요.',
   '[{"all":["put me down"]},{"any":["two","2"]}]',
   'Then put me down for two, please.',
   '["Put it on the top shelf, please.","I''m down the street, at the house with the blue door.","Just one bag. Paper is fine."]',
   '["\\"Put me down for …\\" = write my name next to that number.","Key words: put me down for two"]', '["\\"Put me down for …\\"는 그 수량으로 내 이름을 적어 달라는 뜻입니다.","핵심 단어: put me down for two"]',
   'mike', 'Two it is. Here''s your slip. Just show it at the register.', '두 개로 했어요. 여기 쪽지요. 계산할 때 보여 주기만 하면 돼요.'),
  ('dk_w2_market', 4, 'mike',
   'You still need dessert for four o''clock.', '네 시에 가져갈 디저트가 여전히 필요합니다.',
   'Do you still need ice cream for today? The store brand isn''t on sale, but it''s a dollar cheaper anyway.', 'Say that will do: at a barbecue, nobody will be able to tell the difference.', '그거면 된다고 하세요. 바비큐에서는 아무도 차이를 모를 거라고요.',
   '[{"all":["that will do"]},{"all":["thatll do"]},{"all":["tell the difference"]},{"all":["store brand"]}]',
   'That''ll do. At a barbecue, nobody will be able to tell the difference.',
   '["That will be all. Keep the change.","Tell me about it. Mondays are the worst.","I can''t tell time without my glasses."]',
   '["Accept the cheaper substitute cheerfully.","Key words: that''ll do, tell the difference"]', '["더 싼 대체품을 기분 좋게 받아들이세요.","핵심 단어: that''ll do, tell the difference"]',
   'mike', 'Your secret''s safe with me. That''s four forty-nine.', '비밀은 지켜 드릴게요. 4달러 49센트예요.'),
  ('dk_w2_market', 5, 'mike',
   'Mike puts the ice cream in an insulated bag.', '마이크가 아이스크림을 보냉 봉투에 담습니다.',
   'Oh, and did the hardware store have your charcoal last week?', 'Say they did, thank him for the tip, and tell him he saved the day.', '있었다고 하고, 알려 줘서 고맙다고, 덕분에 살았다고 하세요.',
   '[{"all":["thanks for the tip"]},{"all":["saved the day"]},{"all":["thank you for the tip"]}]',
   'They did. Thanks for the tip. You saved the day.',
   '["They did not. The flight was full.","I left the tip on the table.","I saved the receipt, just in case."]',
   '["Here \\"tip\\" means a piece of advice, not money.","Key words: thanks for the tip, saved the day"]', '["여기서 tip은 돈이 아니라 도움이 되는 정보라는 뜻입니다.","핵심 단어: thanks for the tip, saved the day"]',
   'mike', 'Glad to hear it. Enjoy the barbecue, and don''t let that melt!', '다행이네요. 바비큐 맛있게 하시고, 그거 녹지 않게 하세요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_w2_market.sold_out', 'dk_w2_market', 'The ice cream is sold out.', '아이스크림이 다 팔렸어요.', 'None left to buy. The cashier may say "We''re cleaned out."', '살 수 있는 것이 남아 있지 않다는 뜻입니다. 계산원은 "We''re cleaned out."이라고도 합니다.', 'shopping'),
  ('dk_w2_market.in_the_back', 'dk_w2_market', 'Do you have any more in the back?', '창고에 더 있어요?', '"In the back" = in the stockroom, behind the sales floor.', 'in the back은 매장 뒤편의 창고를 말합니다.', 'shopping'),
  ('dk_w2_market.rain_check', 'dk_w2_market', 'Could I get a rain check?', '레인 체크를 받을 수 있을까요?', 'In a store: a slip that lets you buy a sold-out sale item later at the sale price. With friends, "take a rain check" means "another time".', '가게에서는 다 팔린 할인 품목을 나중에 할인 가격으로 살 수 있게 해 주는 쪽지입니다. 친구 사이에서 take a rain check는 다음 기회에라는 뜻입니다.', 'shopping'),
  ('dk_w2_market.good_for', 'dk_w2_market', 'It''s good for thirty days.', '30일 동안 쓸 수 있어요.', '"Good for" + time = valid for that long.', '"good for + 기간"은 그 기간 동안 유효하다는 뜻입니다.', 'shopping'),
  ('dk_w2_market.limit_per_customer', 'dk_w2_market', 'a limit of two per customer', '고객 한 명에 두 개까지', 'Common on sale signs: each shopper may buy only that many.', '할인 표지에 흔한 문구로, 한 사람이 그 수량까지만 살 수 있다는 뜻입니다.', 'shopping'),
  ('dk_w2_market.put_me_down', 'dk_w2_market', 'Put me down for two.', '두 개로 적어 주세요.', 'Asks someone to write your name on a list for that amount.', '그 수량으로 내 이름을 명단에 적어 달라는 말입니다.', 'shopping'),
  ('dk_w2_market.store_brand', 'dk_w2_market', 'the store brand', '매장 자체 브랜드', 'The store''s own, cheaper version of a product.', '가게가 자체적으로 내놓는 더 저렴한 제품입니다.', 'shopping'),
  ('dk_w2_market.thanks_for_the_tip', 'dk_w2_market', 'Thanks for the tip.', '알려 줘서 고마워요.', 'A tip can be useful advice, not only money for service.', 'tip은 서비스에 주는 돈뿐 아니라 유용한 조언도 뜻합니다.', 'small-talk');

-- dk_w2_brunch: A rainy Sunday at the Sunny Side

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_brunch', 1, 'rosa',
   'Sunday. It has been raining since dawn. The diner''s windows are fogged up, and every booth is taken. You shake off your umbrella at the door.', '일요일입니다. 새벽부터 비가 옵니다. 다이너 창문에는 김이 서렸고 부스 자리는 모두 찼습니다. 문 앞에서 우산의 물기를 텁니다.',
   'Derek! Come in out of the rain, hon. It''s a twenty-minute wait for a booth, or you can sit at the counter right now.', 'Say the counter is fine by you, and that you are in no hurry today.', '카운터 자리면 좋다고 하고, 오늘은 급할 게 없다고 하세요.',
   '[{"all":["fine by me"]},{"all":["in no hurry"]},{"any":["counter"]}]',
   'The counter''s fine by me. I''m in no hurry today.',
   '["I''ll wait outside. It''s a beautiful day.","A booth for six, please. We''re celebrating.","I''m in a rush. Just a coffee to go."]',
   '["Choose the seat and say you have time.","Key words: fine by me, in no hurry"]', '["자리를 고르고 시간 여유가 있다고 말하세요.","핵심 단어: fine by me, in no hurry"]',
   'rosa', 'That''s what Sundays are for. Coffee''s on its way.', '일요일은 그러라고 있는 거죠. 커피 금방 가져올게요.'),
  ('dk_w2_brunch', 2, 'rosa',
   'She pours your coffee and points her pencil at the board.', '그녀가 커피를 따르고 연필로 메뉴판을 가리킵니다.',
   'What''ll it be? The brunch menu''s on the board.', 'Order the veggie omelet with hash browns, and ask her to make them extra crispy.', '채소 오믈렛에 해시 브라운을 주문하고, 해시 브라운은 아주 바삭하게 해 달라고 하세요.',
   '[{"all":["extra crispy"]},{"any":["omelet","omelette"]},{"all":["hash browns"]}]',
   'I''ll have the veggie omelet with hash browns. Could you make them extra crispy?',
   '["I''ll have the fish tacos from the truck.","Could you make it a double room?","I''ll have it done by Friday."]',
   '["Order, then say exactly how you like it cooked.","Key words: omelet, hash browns, extra crispy"]', '["주문하고, 어떻게 익히면 좋은지 정확히 말하세요.","핵심 단어: omelet, hash browns, extra crispy"]',
   'rosa', 'Extra crispy, you got it.', '아주 바삭하게, 알겠어요.'),
  ('dk_w2_brunch', 3, 'rosa',
   'She keeps writing.', '그녀가 계속 받아 적습니다.',
   'It comes with toast. Wheat or sourdough? Butter on it?', 'Choose sourdough, with the butter on the side.', '사워도우로 하고, 버터는 따로 달라고 하세요.',
   '[{"all":["on the side"]},{"any":["sourdough","wheat"]}]',
   'Sourdough, please, with the butter on the side.',
   '["Paper, please. I forgot my own bag.","The aisle, please, near the front.","Medium, please, with room for cream."]',
   '["\\"On the side\\" = in a separate dish, not on the food.","Key words: sourdough, on the side"]', '["on the side는 음식 위가 아니라 따로 담아 달라는 뜻입니다.","핵심 단어: sourdough, on the side"]',
   'rosa', 'Sourdough, butter on the side. Be right back, hon.', '사워도우에 버터는 따로. 금방 올게요.'),
  ('dk_w2_brunch', 4, 'rosa',
   'Your plate is half empty. Rosa comes by with the coffee pot.', '접시가 절반쯤 비었습니다. 로사가 커피포트를 들고 옵니다.',
   'More coffee? So how''s that new kid doing? He was in here yesterday, telling me all about some big trip.', 'Say yes to a warm-up, and tell her he closed his first deal and you could not be prouder.', '커피를 조금만 더 달라고 하고, 그가 첫 계약을 따냈고 더없이 자랑스럽다고 하세요.',
   '[{"all":["warm up"]},{"any":["proud","prouder"]},{"all":["top off"]},{"all":["first deal"]}]',
   'Just a warm-up, thanks. He closed his first deal this week. I couldn''t be prouder.',
   '["No, thanks. He moved to Ridgeport last year.","Just the check. I''m late for a flight.","He''s out sick. He caught a cold."]',
   '["A \\"warm-up\\" is a little more hot coffee in your cup.","Key words: a warm-up, closed his first deal, couldn''t be prouder"]', '["warm-up은 잔에 뜨거운 커피를 조금 더 채워 주는 것입니다.","핵심 단어: a warm-up, closed his first deal, couldn''t be prouder"]',
   'rosa', 'Good for him! He had a good teacher, I bet.', '잘됐네요! 좋은 선생님을 만난 덕이겠죠.'),
  ('dk_w2_brunch', 5, 'rosa',
   'The omelet was huge. You put down your fork.', '오믈렛이 아주 컸습니다. 포크를 내려놓습니다.',
   'You''re slowing down. Want me to wrap that up for you?', 'Say yes, please: ask for a box for the rest, and the check whenever she gets a chance.', '그래 달라고 하세요. 남은 음식을 담을 상자를 부탁하고, 계산서는 시간 날 때 달라고요.',
   '[{"any":["box"]},{"all":["get a chance"]},{"all":["to go"]}]',
   'Yes, please. Could I get a box for the rest? And the check, whenever you get a chance.',
   '["Yes, please. Wrap it as a gift.","No, I''ll finish it on the plane.","Could I get a bigger cart?"]',
   '["Taking leftovers home is normal in the US.","Key words: a box for the rest, whenever you get a chance"]', '["미국에서는 남은 음식을 싸 가는 것이 흔한 일입니다.","핵심 단어: a box for the rest, whenever you get a chance"]',
   'rosa', 'One box, one check. That''s sixteen twenty-four with tax.', '상자 하나, 계산서 하나. 세금 포함 16달러 24센트예요.'),
  ('dk_w2_brunch', 6, 'rosa',
   'The check says $16.24. You take a twenty out of your wallet. About eighteen percent of fifteen dollars is $2.70.', '계산서에는 16.24달러라고 적혀 있습니다. 지갑에서 20달러짜리를 꺼냅니다. 15달러의 18퍼센트쯤이면 2.70달러입니다.',
   'No rush, hon.', 'Give her the twenty, ask for a dollar back, and say the rest is for her.', '20달러를 주고, 1달러만 거슬러 달라고 하고, 나머지는 그녀 몫이라고 하세요.',
   '[{"all":["dollar back"]},{"all":["rest is for you"]},{"all":["rest is yours"]}]',
   'Here''s a twenty. Could I get a dollar back? The rest is for you.',
   '["Here''s my ID. Could I get a room key?","Could I get my money back? It doesn''t fit.","The rest is in the trunk of my car."]',
   '["With cash, say how much change you want; the rest is the tip.","Key words: a dollar back, the rest is for you"]', '["현금으로 낼 때는 거스름돈을 얼마 받을지 말하세요. 나머지가 팁입니다.","핵심 단어: a dollar back, the rest is for you"]',
   'rosa', 'You''re a sweetheart. Stay dry out there!', '정말 다정하시네요. 비 맞지 말고 가요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_w2_brunch.fine_by_me', 'dk_w2_brunch', 'The counter''s fine by me.', '저는 카운터 자리 좋아요.', '"Fine by me" = I have no problem with that.', 'fine by me는 나는 그래도 괜찮다는 뜻입니다.', 'food'),
  ('dk_w2_brunch.in_no_hurry', 'dk_w2_brunch', 'I''m in no hurry.', '급할 거 없어요.', 'You have plenty of time. The opposite: "I''m in a rush."', '시간이 넉넉하다는 뜻입니다. 반대는 "I''m in a rush."입니다.', 'small-talk'),
  ('dk_w2_brunch.extra_crispy', 'dk_w2_brunch', 'Could you make them extra crispy?', '아주 바삭하게 해 주시겠어요?', 'Diners cook to order. Also: "well done", "lightly toasted".', '다이너는 주문대로 조리해 줍니다. well done, lightly toasted 같은 말도 씁니다.', 'food'),
  ('dk_w2_brunch.on_the_side', 'dk_w2_brunch', 'with the butter on the side', '버터는 따로 담아서', 'Served separately, so you add as much as you want.', '따로 담아 줘서 원하는 만큼 넣을 수 있습니다.', 'food'),
  ('dk_w2_brunch.warm_up', 'dk_w2_brunch', 'Just a warm-up, thanks.', '조금만 더 채워 주세요.', 'A little more hot coffee in a cup that is not empty. Refills are usually free at a diner.', '비지 않은 잔에 뜨거운 커피를 조금 더 채우는 것입니다. 다이너에서는 리필이 대개 무료입니다.', 'food'),
  ('dk_w2_brunch.couldnt_be_prouder', 'dk_w2_brunch', 'I couldn''t be prouder.', '더없이 자랑스러워요.', '"Couldn''t be" + comparative = as much as possible.', '"couldn''t be + 비교급"은 그 이상일 수 없을 만큼이라는 뜻입니다.', 'small-talk'),
  ('dk_w2_brunch.get_a_chance', 'dk_w2_brunch', 'whenever you get a chance', '시간 날 때', 'A polite way to ask without hurrying a busy person.', '바쁜 사람을 재촉하지 않고 정중하게 부탁하는 표현입니다.', 'food'),
  ('dk_w2_brunch.dollar_back', 'dk_w2_brunch', 'Could I get a dollar back?', '1달러만 거슬러 주시겠어요?', 'When you pay cash, say how much change you want. What is left is the tip.', '현금으로 낼 때 거스름돈을 얼마 받을지 말합니다. 남는 돈이 팁입니다.', 'money');

